export const stages=[['learn','Understand',10],['words','Build vocabulary',10],['practice','Practise',15],['listen','Listen closely',10],['speak','Speak aloud',10],['write','Write & reflect',15]];
const vocab=s=>s.split('|').map(x=>{const [de,en]=x.split('=');return {de,en};});
export const units=[
{id:1,title:'Your first Hallo',de:'Hallo, Deutschland!',icon:'☀',color:'peach',subtitle:'Meet people. Find your voice.',goal:'Introduce yourself, greet someone and ask for help.',vocab:vocab('Hallo=hello|Guten Morgen=good morning|Guten Tag=good day / hello|Guten Abend=good evening|Auf Wiedersehen=goodbye (formal)|Tschüss=bye (informal)|bitte=please / you’re welcome|danke=thank you|ja=yes|nein=no|Entschuldigung=excuse me / sorry|ich=I|du=you (informal singular)|Sie=you (formal)|heißen=to be called|sein=to be|kommen=to come|wohnen=to live / reside|Deutschland=Germany|Deutsch=German (language)|Englisch=English (language)|der Name, die Namen=name|gut=good|langsam=slowly'),dialogue:[['Hallo! Ich heiße Mira. Und du?','Hello! My name is Mira. And you?'],['Ich heiße Sami. Ich komme aus Ägypten.','My name is Sami. I come from Egypt.'],['Ich wohne in Berlin. Wo wohnst du?','I live in Berlin. Where do you live?'],['Ich wohne in Kairo. Ich lerne Deutsch.','I live in Cairo. I am learning German.'],['Wie bitte? Bitte noch einmal, langsam.','Pardon? Once again, slowly, please.']],readQ:['Where does Sami live?','Kairo','Berlin','Hamburg'],mission:'Make a 45-second introduction: greet a new neighbour, say your name, home country and city, then ask their name. Ask them to repeat one thing.',missionModel:'Hallo! Ich heiße Sami. Ich komme aus Ägypten. Ich wohne in Kairo. Wie heißt du? Wo wohnst du? Wie bitte? Bitte noch einmal.'},
{id:2,title:'People & connections',de:'Das bin ich',icon:'☺',color:'lavender',subtitle:'Names, numbers and new friends.',goal:'Exchange contact details and talk about work and hobbies.',vocab:vocab('null=zero|eins=one|zwei=two|drei=three|vier=four|fünf=five|sechs=six|sieben=seven|acht=eight|neun=nine|zehn=ten|elf=eleven|zwölf=twelve|zwanzig=twenty|dreißig=thirty|hundert=one hundred|der Beruf, die Berufe=profession|arbeiten=to work|lernen=to learn|spielen=to play|lesen=to read|gern=gladly / like to|die Nummer, die Nummern=number|die E-Mail, die E-Mails=email'),dialogue:[['Was machst du beruflich?','What do you do for work?'],['Ich bin Lehrerin. Und du?','I am a teacher. And you?'],['Ich arbeite im Café. Ich lerne Deutsch.','I work in the café. I am learning German.'],['Liest du gern?','Do you like reading?'],['Ja. Meine Nummer ist null eins sieben sechs, zwei drei vier fünf.','Yes. My number is zero one seven six, two three four five.']],readQ:['What is the woman’s job?','Lehrerin','Ärztin','Studentin'],mission:'Create a club registration card with your name, city, email, phone number and hobby. Spell your surname aloud, say the phone number digit by digit, then ask a new member three questions.',missionModel:'Name: Sami Ali. Wohnort: Kairo. E-Mail: sami@example.com. Telefonnummer: 0176 2345. Hobby: Lesen. Wie heißt du? Wo wohnst du? Was machst du gern?'},
{id:3,title:'Around the city',de:'Unterwegs in der Stadt',icon:'⌂',color:'blue',subtitle:'Find your way, one question at a time.',goal:'Name places, ask directions and understand simple instructions.',vocab:vocab('der Bahnhof, die Bahnhöfe=train station|die Straße, die Straßen=street|der Platz, die Plätze=square / place|die Apotheke, die Apotheken=pharmacy|das Hotel, die Hotels=hotel|das Museum, die Museen=museum|der Supermarkt, die Supermärkte=supermarket|die Bank, die Banken=bank / bench|das Café, die Cafés=café|die Schule, die Schulen=school|der Bus, die Busse=bus|die Bahn, die Bahnen=railway / train|das Fahrrad, die Fahrräder=bicycle|das Auto, die Autos=car|links=left|rechts=right|geradeaus=straight ahead|hier=here|dort=there|wo=where (location)|gehen=to go / walk|fahren=to go by vehicle|klein=small|groß=big / tall'),dialogue:[['Entschuldigung, wo ist der Bahnhof?','Excuse me, where is the train station?'],['Gehen Sie geradeaus und dann links.','Go straight ahead and then left.'],['Ist das dort der Bahnhof?','Is that the train station over there?'],['Nein, das ist ein Hotel. Der Bahnhof ist rechts.','No, that is a hotel. The station is on the right.'],['Vielen Dank!','Thank you very much!']],readQ:['What is the building first mistaken for the station?','ein Hotel','eine Schule','ein Museum'],mission:'Draw a street with a station, café, pharmacy and hotel. Give a visitor four directions. Describe two places and correct one mistaken identification.',missionModel:'Gehen Sie geradeaus. Gehen Sie dann links. Der Bahnhof ist rechts. Das Hotel ist groß. Das Café ist klein. Das ist kein Museum, das ist eine Schule.'},
{id:4,title:'A taste of German',de:'Guten Appetit!',icon:'♧',color:'yellow',subtitle:'From the bakery to your first café order.',goal:'Shop for food, express preferences and order politely.',vocab:vocab('das Brot, die Brote=bread / loaf|das Brötchen, die Brötchen=bread roll|die Butter=butter|der Käse=cheese|die Milch=milk|das Ei, die Eier=egg|der Apfel, die Äpfel=apple|die Banane, die Bananen=banana|die Kartoffel, die Kartoffeln=potato|die Tomate, die Tomaten=tomato|der Reis=rice|die Nudeln=pasta / noodles|das Fleisch=meat|der Fisch, die Fische=fish|das Wasser=water|der Kaffee, die Kaffees=coffee|der Tee, die Tees=tea|der Saft, die Säfte=juice|kaufen=to buy|essen=to eat|trinken=to drink|möchten=would like|kosten=to cost|die Rechnung, die Rechnungen=bill'),dialogue:[['Guten Tag. Ich möchte zwei Brötchen und einen Kaffee.','Hello. I would like two bread rolls and a coffee.'],['Mit Milch?','With milk?'],['Nein, ohne Milch, bitte. Was kostet das?','No, without milk, please. How much is that?'],['Das kostet sechs Euro fünfzig.','That costs six euros fifty.'],['Hier, bitte. Danke!','Here you are. Thank you!']],readQ:['How much is the order?','6,50 €','5,60 €','6,15 €'],mission:'Write a shopping list for two meals with quantities. Role-play buying three items, asking the price, ordering a drink and asking for the bill. Repeat with a different preference.',missionModel:'Ich brauche vier Eier, ein Brot und zwei Äpfel. Ich möchte einen Tee ohne Milch. Was kostet das? Die Rechnung, bitte. Ich esse gern Reis.'},
{id:5,title:'Your everyday life',de:'Mein Tag',icon:'◷',color:'mint',subtitle:'Make time for the things that matter.',goal:'Describe routines, tell the time and arrange an appointment.',vocab:vocab('der Montag, die Montage=Monday|der Dienstag, die Dienstage=Tuesday|der Mittwoch, die Mittwoche=Wednesday|der Donnerstag, die Donnerstage=Thursday|der Freitag, die Freitage=Friday|der Samstag, die Samstage=Saturday|der Sonntag, die Sonntage=Sunday|heute=today|morgen=tomorrow|gestern=yesterday|die Uhr, die Uhren=clock / watch|die Stunde, die Stunden=hour|die Minute, die Minuten=minute|der Termin, die Termine=appointment|aufstehen=to get up|anfangen=to begin|einkaufen=to shop|anrufen=to call by phone|frühstücken=to have breakfast|schlafen=to sleep|müssen=to have to|können=to be able to|wollen=to want to|spät=late'),dialogue:[['Wann stehst du auf?','When do you get up?'],['Um sieben Uhr. Um halb neun fange ich an.','At seven. I start at half past eight.'],['Kannst du am Mittwoch ins Café kommen?','Can you come to the café on Wednesday?'],['Leider nicht. Ich muss bis sechs Uhr arbeiten.','Unfortunately not. I have to work until six.'],['Dann am Samstag um zehn?','Then on Saturday at ten?']],readQ:['When does the speaker start work?','8:30','9:30','7:00'],mission:'Plan a weekday with six times, two obligations and one enjoyable activity. Leave a short phone message asking for an appointment; offer another time when the first one is unavailable.',missionModel:'Ich stehe um sieben Uhr auf. Um acht Uhr frühstücke ich. Ich muss arbeiten. Können wir am Freitag um zehn Uhr sprechen? Nein? Dann am Samstag um elf Uhr?'},
{id:6,title:'Friends & family',de:'Zusammen ist es schöner',icon:'♡',color:'peach',subtitle:'Tell your story and make a plan together.',goal:'Describe family, arrange a celebration and talk about yesterday.',vocab:vocab('die Familie, die Familien=family|die Mutter, die Mütter=mother|der Vater, die Väter=father|die Eltern=parents|die Schwester, die Schwestern=sister|der Bruder, die Brüder=brother|das Kind, die Kinder=child|die Tochter, die Töchter=daughter|der Sohn, die Söhne=son|der Freund, die Freunde=friend (male) / boyfriend|die Freundin, die Freundinnen=friend (female) / girlfriend|der Geburtstag, die Geburtstage=birthday|die Einladung, die Einladungen=invitation|die Party, die Partys=party|das Geschenk, die Geschenke=gift|der Januar=January|der Februar=February|der März=March|der April=April|der Mai=May|der Juni=June|der Juli=July|der August=August|der September=September|der Oktober=October|der November=November|der Dezember=December'),dialogue:[['Mein Bruder hat am dritten Mai Geburtstag.','My brother’s birthday is on May third.'],['Machst du eine Party für ihn?','Are you having a party for him?'],['Ja. Ich lade dich ein. Hast du am Samstag Zeit?','Yes. I am inviting you. Do you have time on Saturday?'],['Ja, gern! Gestern war ich krank, aber heute geht es mir gut.','Yes, gladly! Yesterday I was ill, but today I am well.']],readQ:['Who has a birthday?','der Bruder','der Vater','die Schwester'],mission:'Write a 30–40-word invitation with occasion, day, date, time and location. Record an acceptance and a polite refusal. Say two things about yesterday using war and hatte.',missionModel:'Hallo Nora, mein Bruder hat am dritten Mai Geburtstag. Wir machen am Samstag um sechs Uhr eine Party bei mir. Hast du Zeit? Bring bitte etwas zu trinken mit. Viele Grüße, Sami'},
{id:7,title:'A place to call home',de:'Bei mir zu Hause',icon:'⌂',color:'lavender',subtitle:'Rooms, favourite things and a new address.',goal:'Describe a home, locate objects and understand a simple rental advert.',vocab:vocab('die Wohnung, die Wohnungen=apartment|das Haus, die Häuser=house|das Zimmer, die Zimmer=room|die Küche, die Küchen=kitchen|das Bad, die Bäder=bathroom|das Schlafzimmer, die Schlafzimmer=bedroom|der Balkon, die Balkone=balcony|der Garten, die Gärten=garden|der Tisch, die Tische=table|der Stuhl, die Stühle=chair|das Bett, die Betten=bed|der Schrank, die Schränke=cupboard / wardrobe|das Sofa, die Sofas=sofa|die Lampe, die Lampen=lamp|die Tür, die Türen=door|das Fenster, die Fenster=window|die Miete, die Mieten=rent|hell=bright|dunkel=dark|teuer=expensive|billig=cheap|auf=on|unter=under|neben=next to'),dialogue:[['Wie ist deine Wohnung?','What is your apartment like?'],['Sie ist klein, aber hell. Sie hat zwei Zimmer.','It is small but bright. It has two rooms.'],['Wo steht der Tisch?','Where is the table?'],['In der Küche, neben dem Fenster.','In the kitchen, next to the window.'],['Und wie viel kostet die Wohnung?','And how much does the apartment cost?'],['Die Miete ist siebenhundert Euro im Monat.','The rent is seven hundred euros per month.']],readQ:['How many rooms does the apartment have?','zwei','drei','sieben'],mission:'Describe a real or imaginary apartment in six sentences. Include rooms, rent, two opinions and three object locations. Write a short question to a landlord asking the rent and number of rooms.',missionModel:'Meine Wohnung hat zwei Zimmer. Sie ist hell. Die Miete ist 700 Euro. Der Tisch steht in der Küche. Das Buch liegt auf dem Tisch. Wie viele Zimmer hat die Wohnung?'},
{id:8,title:'Out & about',de:'Auf Reisen',icon:'↗',color:'blue',subtitle:'Tickets, journeys and small adventures.',goal:'Buy a ticket, check in and discuss a completed journey.',vocab:vocab('die Reise, die Reisen=journey / trip|der Urlaub, die Urlaube=holiday / vacation|der Zug, die Züge=train|das Gleis, die Gleise=railway platform / track|die Fahrkarte, die Fahrkarten=ticket|der Flughafen, die Flughäfen=airport|das Flugzeug, die Flugzeuge=airplane|der Koffer, die Koffer=suitcase|der Pass, die Pässe=passport|die Haltestelle, die Haltestellen=stop|die Ankunft, die Ankünfte=arrival|die Abfahrt, die Abfahrten=departure|die Verspätung, die Verspätungen=delay|buchen=to book|reservieren=to reserve|umsteigen=to change trains / buses|ankommen=to arrive|abfahren=to depart|besuchen=to visit|bleiben=to stay|nach=to (cities / most countries)|mit=with / by|ohne=without|zurück=back'),dialogue:[['Eine Fahrkarte nach Köln, bitte.','A ticket to Cologne, please.'],['Einfach oder hin und zurück?','One way or return?'],['Hin und zurück. Wann fährt der Zug ab?','Return. When does the train leave?'],['Um vierzehn Uhr zehn, von Gleis drei.','At 14:10, from platform three.'],['Muss ich umsteigen?','Do I have to change trains?'],['Nein, der Zug fährt direkt.','No, the train goes directly.']],readQ:['Which platform does the train leave from?','3','10','14'],mission:'Plan a trip: destination, transport, departure, ticket type and hotel booking. Then write a postcard with three things you did and one place you visited.',missionModel:'Ich fahre mit dem Zug nach Köln. Eine Fahrkarte hin und zurück, bitte. Ich habe ein Zimmer reserviert. Gestern bin ich angekommen. Ich habe das Museum besucht. Es war schön.'},
{id:9,title:'Feeling good',de:'Gesund und munter',icon:'✚',color:'mint',subtitle:'Say how you feel and ask for help.',goal:'Describe symptoms, arrange a doctor’s appointment and understand simple advice.',vocab:vocab('der Kopf, die Köpfe=head|der Bauch, die Bäuche=belly / stomach area|der Rücken, die Rücken=back|der Hals, die Hälse=throat / neck|der Arm, die Arme=arm|das Bein, die Beine=leg|die Hand, die Hände=hand|der Fuß, die Füße=foot|der Zahn, die Zähne=tooth|der Arzt, die Ärzte=doctor (male)|die Ärztin, die Ärztinnen=doctor (female)|die Praxis, die Praxen=medical practice|die Schmerzen=pain / pains|das Fieber=fever|der Husten=cough|die Tablette, die Tabletten=tablet / pill|krank=ill|gesund=healthy|müde=tired|wehtun=to hurt|helfen=to help|sollen=to be supposed to / should|dürfen=to be allowed to|brauchen=to need'),dialogue:[['Guten Morgen. Ich brauche einen Termin.','Good morning. I need an appointment.'],['Was fehlt Ihnen?','What is wrong?'],['Mein Hals tut weh. Ich habe Husten.','My throat hurts. I have a cough.'],['Können Sie heute um elf Uhr kommen?','Can you come today at eleven?'],['Ja. Vielen Dank.','Yes. Thank you very much.']],readQ:['What appointment time is offered?','11:00','12:00','10:00'],mission:'Role-play a receptionist and patient: give a name, describe two symptoms and agree an appointment. Practise three polite requests and explain a sign that prohibits something.',missionModel:'Guten Tag, ich heiße Sami Ali. Mein Kopf tut weh. Ich habe Fieber. Haben Sie heute einen Termin? Können Sie bitte langsam sprechen? Hier darf man nicht rauchen.'},
{id:10,title:'Finding your style',de:'Das gefällt mir',icon:'✦',color:'yellow',subtitle:'Shop, compare and choose.',goal:'Ask about clothes, sizes, colours, prices and preferences.',vocab:vocab('die Hose, die Hosen=trousers|das Hemd, die Hemden=shirt|das Kleid, die Kleider=dress|die Jacke, die Jacken=jacket|der Mantel, die Mäntel=coat|der Pullover, die Pullover=sweater|der Schuh, die Schuhe=shoe|das T-Shirt, die T-Shirts=T-shirt|die Größe, die Größen=size|die Farbe, die Farben=colour|rot=red|blau=blue|grün=green|gelb=yellow|schwarz=black|weiß=white|grau=grey|passen=to fit|gefallen=to please / be liked|anprobieren=to try on|nehmen=to take|bezahlen=to pay|besser=better|lieber=preferably'),dialogue:[['Kann ich die Jacke anprobieren?','May I try on the jacket?'],['Ja, gern. Welche Größe brauchen Sie?','Yes, of course. What size do you need?'],['Größe vierzig. Haben Sie die Jacke auch in Blau?','Size forty. Do you also have the jacket in blue?'],['Ja. Passt sie Ihnen?','Yes. Does it fit you?'],['Ja, sie gefällt mir. Ich nehme sie.','Yes, I like it. I will take it.']],readQ:['Which colour does the customer ask for?','Blau','Rot','Schwarz'],mission:'Choose clothes for a trip and explain your preferences. Role-play asking for a size, trying an item, comparing two prices and paying. Politely reject an unsuitable item.',missionModel:'Ich brauche eine Jacke in Größe 40. Kann ich sie anprobieren? Sie ist zu klein. Haben Sie Größe 42? Die blaue Jacke gefällt mir. Ich bezahle mit Karte.'},
{id:11,title:'Work & new plans',de:'Was kommt als Nächstes?',icon:'▤',color:'peach',subtitle:'Appointments, messages and possibilities.',goal:'Write useful short messages and explain simple plans.',vocab:vocab('das Büro, die Büros=office|die Arbeit=work|die Pause, die Pausen=break|der Kollege, die Kollegen=colleague (male)|die Kollegin, die Kolleginnen=colleague (female)|der Chef, die Chefs=boss (male)|die Chefin, die Chefinnen=boss (female)|der Kurs, die Kurse=course|die Prüfung, die Prüfungen=exam|die Aufgabe, die Aufgaben=task|die Nachricht, die Nachrichten=message|der Brief, die Briefe=letter|die Antwort, die Antworten=answer|die Frage, die Fragen=question|schreiben=to write|antworten=to answer|fragen=to ask|verstehen=to understand|erklären=to explain|beginnen=to begin|enden=to end|nächste Woche=next week|pünktlich=on time|leider=unfortunately'),dialogue:[['Guten Tag, Frau Weber. Ich kann morgen nicht zum Kurs kommen.','Hello, Ms Weber. I cannot come to the course tomorrow.'],['Das ist schade. Können Sie am Freitag kommen?','That is a shame. Can you come on Friday?'],['Ja. Wann beginnt der Kurs?','Yes. When does the course start?'],['Um neun Uhr. Bringen Sie bitte Ihr Buch mit.','At nine. Please bring your book.'],['Vielen Dank. Bis Freitag!','Thank you. See you on Friday!']],readQ:['On which day will the learner come?','Freitag','Donnerstag','Montag'],mission:'Write a formal 30–40-word message: you cannot attend a class. Apologise, give a simple reason, ask for the homework and suggest a new appointment. Read it aloud and check every verb.',missionModel:'Sehr geehrte Frau Weber, leider kann ich morgen nicht zum Kurs kommen. Ich bin krank. Können Sie mir bitte die Aufgaben schicken? Am Freitag habe ich Zeit. Vielen Dank. Mit freundlichen Grüßen, Sami Ali'},
{id:12,title:'Ready for real life',de:'Du schaffst das!',icon:'⚑',color:'lavender',subtitle:'Bring everything together.',goal:'Handle linked everyday situations and assess your next steps.',vocab:vocab('das Wetter=weather|die Sonne=the sun|der Regen=rain|der Schnee=snow|der Wind, die Winde=wind|warm=warm|kalt=cold|heiß=hot|regnen=to rain|schneien=to snow|der Frühling=spring|der Sommer=summer|der Herbst=autumn|der Winter=winter|offen=open|geschlossen=closed|der Eingang, die Eingänge=entrance|der Ausgang, die Ausgänge=exit|die Hilfe=help|wichtig=important|richtig=correct|falsch=wrong|noch einmal=once again|zusammen=together'),dialogue:[['Hallo Sami, am Sonntag ist das Museum geschlossen.','Hello Sami, the museum is closed on Sunday.'],['Schade. Wie ist das Wetter am Samstag?','A pity. What is the weather like on Saturday?'],['Es regnet. Wir können am Samstag ins Museum gehen.','It is raining. We can go to the museum on Saturday.'],['Gut. Treffen wir uns um zehn Uhr am Bahnhof?','Good. Shall we meet at ten at the station?'],['Ja. Bring bitte deine Fahrkarte mit.','Yes. Please bring your ticket.']],readQ:['When will they visit the museum?','Samstag','Sonntag','Montag'],mission:'Complete an A1 day: introduce yourself, read an opening-hours notice, understand a ticket conversation, write an invitation and make three requests. Use the final checkpoint, then revisit your weakest unit.',missionModel:'Ich heiße Sami und wohne in Kairo. Das Museum ist am Sonntag geschlossen. Wir treffen uns am Samstag um zehn Uhr am Bahnhof. Kannst du bitte deine Fahrkarte mitbringen?'}
];

// Each lesson has original teaching notes, annotated examples and contextual production tasks.
const lesson=(unit,title,focus,notes,examples,drills,writing,model,speaking)=>({id:`u${unit}l${lessons.filter(x=>x.unit===unit).length+1}`,unit,title,focus,notes:notes.split('~'),examples:examples.split('|').map(s=>{let [de,en]=s.split('=');return {de,en};}),drills:drills.map(([q,a,why,wrong])=>({q,a,why,wrong})),writing,model,speaking,minutes:70});
export const lessons=[];
const add=(...args)=>lessons.push(lesson(...args));

add(1,'Hello, new world','Greetings, politeness and your first conversation',
'German has friendly and formal ways to address people. Use Hallo with people you know or in relaxed situations. Guten Tag is a safe daytime greeting with strangers. Guten Morgen is for the morning, Guten Abend for the evening. Gute Nacht means good night when leaving for bed, rather than hello at night.~Use du for a friend or another learner. Use the capitalised Sie with an adult stranger in a formal situation. Do not worry about every verb ending yet: learn Wie heißt du? and Wie heißen Sie? as complete phrases. Listen to each example, pause, and say it yourself. German does not need a separate word for “am …-ing”: Ich lerne means I learn or I am learning.~Bitte does several jobs: please, you are welcome, or here you are, depending on context. Danke means thank you. If you miss something, say Wie bitte? or Bitte noch einmal. Asking for repetition is successful communication, not a failure. Practise a greeting, a thank-you and a goodbye in two registers.',
'Guten Morgen!=Good morning!|Hallo! Ich heiße Mira.=Hello! My name is Mira.|Wie heißen Sie?=What is your name? (formal)|Danke! – Bitte!=Thank you! – You’re welcome!|Bitte noch einmal.=Once again, please.|Auf Wiedersehen!=Goodbye! (formal)',
[['Greet a shop assistant during the day.','Guten Tag','Guten Tag works as a polite daytime greeting.',['Gute Nacht','Tschüss']],['Say “thank you”.','Danke','Danke thanks someone; bitte may mean please or you’re welcome.',['Bitte','Nein']],['Ask someone to repeat.','Wie bitte?','This is the polite phrase for “Pardon?”',['Wie viel?','Woher?']],['Which “you” fits a formal first meeting?','Sie','Formal Sie is always capitalised.',['du','ich']]],
'Write two short exchanges, one with a friend and one with a shop assistant. Include a greeting, name question, thank-you and goodbye. Read both aloud twice.',
'Hallo! Ich heiße Sami. Wie heißt du? Danke. Tschüss!\nGuten Tag! Wie heißen Sie? Danke. Auf Wiedersehen!',
'Imagine meeting a neighbour. Greet them, say your name and ask them to repeat theirs. Repeat the exchange formally.');
add(1,'The sounds of German','Alphabet, vowels and useful sound patterns',
'German uses the Latin alphabet plus ä, ö, ü and ß. A noun begins with a capital letter: Name, Land, Sprache. Letters are not pronounced exactly as in English. The letter w is usually like English v; v is often like f in Vater, although borrowed words vary. The letter j sounds like English y in yes. The letter z sounds like ts in cats. Listen to Zimmer and zwei.~Learn letter groups as units. In mein, ei sounds like English “eye”. In sieben, ie is a long ee. In Deutsch and neu, eu sounds like “oy”. Sch sounds like English sh. At the start of a native word, sp and st usually begin with sh: sprechen, Straße. The ch in ich is a soft friction sound made high in the mouth; after a, o or u, as in Bach, it is farther back. English approximations are only starting points.~Umlauts change meaning, so keep them: schon and schön are different words. To try ü, shape your lips for oo while attempting ee; for ö, round your lips while saying a vowel like the one in English “her”, without an r. Listen and compare rather than forcing an English substitute. If your keyboard lacks the letters, ae, oe, ue and ss can replace ä, ö, ü and ß when needed.',
'mein=my|sieben=seven|Deutsch=German|Wasser=water|zwei=two|Tschüss!=Bye!',
[['Which spelling has the “eye” vowel?','mein','ei is pronounced as one sound, approximately English “eye”.',['sieben','Sie']],['Which spelling has a long “ee” vowel?','sieben','ie normally marks a long ee sound.',['mein','nein']],['Which letter usually sounds like English v?','w','German w usually sounds like English v.',['j','z']],['Keyboard substitute for ü?','ue','Use ue if ü is unavailable. u alone changes the spelling.',['u','ou']]],
'Copy ten course words with special sounds. Underline ei, ie, sch, ch or an umlaut. Write your own name and practise spelling it using the alphabet tool in the study room.',
'mein: ei; sieben: ie; Deutsch: eu; Tschüss: ü; ich: ch; Schule: sch; zwei: z; Wasser: w; heißen: ei, ß; schön: sch, ö.',
'Play mein, sieben, Deutsch, Wasser and zwei. Shadow each word three times, then record them without the model. Listen for vowels, not speed.');
add(1,'I am, you are','Personal pronouns and sein',
'A pronoun replaces a person’s name. Start with ich (I), du (you, familiar singular), er (he), sie (she), es (it), wir (we), ihr (you, familiar plural), sie (they), and Sie (formal you, singular or plural). Context distinguishes sie from Sie in speech. The capital letter distinguishes formal Sie in writing except at the start of a sentence.~Sein means “to be” and has irregular forms: ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind. Learn the pronoun and form together. In a simple statement, the conjugated verb is in the second position: Ich bin Sami. Position means a sentence part, not necessarily a single word. For now, put the person first and the verb second.~Unlike English, a profession after sein normally has no indefinite article: Ich bin Lehrer. You can also use sein with an adjective: Ich bin müde. German adjectives used this way do not change their ending for the person. Read each example and swap the subject: turn ich into wir and change bin into sind.',
'Ich bin Sami.=I am Sami.|Du bist nett.=You are nice.|Sie ist Lehrerin.=She is a teacher.|Wir sind hier.=We are here.|Ihr seid müde.=You (plural) are tired.|Sind Sie Herr Ali?=Are you Mr Ali?',
[['Ich ___ Sami.','bin','Sein has the special ich form bin.',['ist','bist']],['Wir ___ hier.','sind','Wir means we and takes sind, not seid (which belongs to ihr).',['seid','bin']],['Du ___ nett.','bist','Du means familiar singular you and takes bist, not bin or ist.',['bin','ist']],['Ihr ___ müde.','seid','Ihr is familiar plural you and uses seid.',['sind','ist']]],
'Write six short sentences about yourself and imaginary classmates. Use ich, du, er or sie, wir, ihr and Sie at least once. Check every form of sein against the table.',
'Ich bin Sami. Du bist nett. Sie ist Lehrerin. Wir sind hier. Ihr seid müde. Sind Sie Herr Ali?',
'Say who you are. Introduce two imaginary friends, then describe your group using wir. Switch between singular and plural.');
add(1,'Where are you from?','Regular verbs and W-questions',
'The dictionary form of a German verb is called its infinitive; many end in -en. Remove -en from wohnen to get wohn-, then add endings: ich wohne, du wohnst, er/sie/es wohnt, wir wohnen, ihr wohnt, sie/Sie wohnen. Kommen and lernen follow the same basic pattern. Heißen is slightly special: du heißt, not heißst.~Questions beginning with a question word use that word first and the conjugated verb second: Wo wohnst du? Wo asks where someone lives; woher asks where they come from. Wer means who, was means what and wie means how. A statement answers with subject then verb: Ich wohne in Kairo. German uses the present tense for both “I live” and “I am living”.~Use aus for origin: Ich komme aus Ägypten. Use in for residence: Ich wohne in Berlin. Many country names stand alone, but some have articles: aus der Schweiz, aus der Türkei, aus den USA. Learn those as chunks for now. You are not expected to master their cases in this first unit. For a full introduction, link four short sentences instead of constructing one complicated one.',
'Ich komme aus Ägypten.=I come from Egypt.|Woher kommst du?=Where are you from?|Wo wohnen Sie?=Where do you live? (formal)|Ich wohne in Kairo.=I live in Cairo.|Wir lernen Deutsch.=We are learning German.|Sie kommt aus der Schweiz.=She comes from Switzerland.',
[['Woher ___ du?','kommst','The du ending is -st: kommst.',['komme','kommen']],['Ask about someone’s home city.','Wo wohnst du?','Wo asks location; woher asks origin.',['Woher wohnst du?','Was wohnst du?']],['Ich komme ___ Ägypten.','aus','Origin is expressed with aus.',['in','um']],['Wir ___ Deutsch.','lernen','Wir uses the infinitive-shaped form lernen.',['lernt','lernst']]],
'Write a four-sentence profile: name, country, city and language. Then write three questions to ask another learner. Use the answers aloud to hold both sides of a conversation.',
'Ich heiße Sami. Ich komme aus Ägypten. Ich wohne in Kairo. Ich lerne Deutsch. Wie heißt du? Woher kommst du? Wo wohnst du?',
'Give a 30-second introduction without looking. Then ask and answer the three questions in a different order.');
add(2,'Numbers you can use','Numbers, prices and contact details',
'Learn null to zwölf as individual words. Most numbers from thirteen to nineteen combine a unit and zehn: dreizehn, vierzehn, fünfzehn. Watch the shortened forms sechzehn and siebzehn. The tens include zwanzig, dreißig, vierzig, fünfzig, sechzig, siebzig, achtzig and neunzig. Say a phone number digit by digit; do not try to turn it into one huge number.~From 21 to 99, the spoken order puts the units before the tens: einundzwanzig literally means one-and-twenty, and vierunddreißig is 34. Eins loses its s in einundzwanzig. German writes these number words together, but you can use digits in forms. For prices, a comma separates euros and cents in German notation: 3,50 €. Say drei Euro fünfzig.~A registration form may ask for Vorname (given name), Nachname (family name), Wohnort (town of residence) and Telefonnummer. Email addresses use at or the English-sounding Ät for @ and Punkt for a dot. Take time to confirm details: Noch einmal, bitte. When listening to a number, write digits immediately and compare with a second playback.',
'einundzwanzig=21|vierunddreißig=34|sechzehn=16|siebzehn=17|Das kostet drei Euro fünfzig.=That costs three euros fifty.|Meine Nummer ist null eins sieben sechs.=My number is zero one seven six.',
[['Which number is vierunddreißig?','34','Say the units first: vier + und + dreißig.',['43','30']],['Which word means 16?','sechzehn','The s from sechs is dropped in sechzehn.',['sechszehn','sechzig']],['How is 21 written?','einundzwanzig','Eins becomes ein before und.',['einsundzwanzig','zwanzigeins']],['What price is drei Euro fünfzig?','3,50 €','Euro amount first, then cents. German prices use a decimal comma.',['3,15 €','5,30 €']]],
'Write a contact card using an invented name, city, phone number and email. Write five prices in digits and words. Dictate your number, wait a minute, then check what you remember.',
'Vorname: Sami. Nachname: Ali. Wohnort: Kairo. Telefonnummer: 0176 2345. E-Mail: sami@example.com. 2,40 €: zwei Euro vierzig. 5,20 €: fünf Euro zwanzig.',
'Say 13, 16, 17, 21, 34 and 48. Read an invented eight-digit phone number slowly, then ask for it again and repeat it to confirm.');
add(2,'The people in your world','Noun gender, articles and plurals',
'Every German noun has a grammatical gender. The definite article, roughly English “the”, is der for masculine, die for feminine and das for neuter in the subject form. These categories are part of the word and do not always match natural gender. Learn das Mädchen (girl) as a whole phrase rather than trying to guess from meaning. Capitalise nouns wherever they occur in a sentence.~Plural nouns use die in this basic form, regardless of singular gender: der Freund → die Freunde; das Kind → die Kinder. There are several plural patterns, including -e, -er, -n/-en, -s and no ending. Sometimes a vowel also changes: der Bruder → die Brüder. There is no universal ending you can safely add to every noun.~Make a vocabulary entry a three-part package: article + singular, plural, meaning. For example: der Beruf, die Berufe, profession. In a sentence, the article tells you something about the noun; later it will also show the noun’s job in the sentence. For now, practise identifying the person or thing as the subject: Der Lehrer ist hier. Die Lehrer sind hier.',
'der Freund, die Freunde=the friend, the friends|die Freundin, die Freundinnen=the female friend, the female friends|das Kind, die Kinder=the child, the children|Der Lehrer ist hier.=The teacher is here.|Die Lehrer sind hier.=The teachers are here.|Das Mädchen lernt Deutsch.=The girl is learning German.',
[['The basic plural article is ___.','die','All genders use die in the nominative plural.',['der','das']],['Choose the correctly capitalised noun.','der Beruf','German nouns begin with capital letters.',['der beruf','Der beruf']],['Plural of das Kind?','die Kinder','Kind has the plural Kinder; learn both together.',['die Kinds','das Kinder']],['Die Lehrer ___ hier.','sind','Die Lehrer is plural, so sein becomes sind.',['ist','bist']]],
'Create eight noun entries with article, plural and English meaning. Write four sentences contrasting one person or object with more than one. Check ist versus sind.',
'der Freund, die Freunde: friend. das Kind, die Kinder: child. Der Freund ist hier. Die Freunde sind hier. Das Kind ist müde. Die Kinder sind müde.',
'Point to imagined people and say one singular sentence, then a plural sentence. Always say the article with the noun.');
add(2,'What do you do?','Jobs, regular verb endings and haben',
'To ask about work, say Was machen Sie beruflich? A simple answer uses sein without an article: Ich bin Arzt; Ich bin Ärztin. Many profession words distinguish a male and female form, often with -in, but do not assume every job follows one pattern. You may also say Ich arbeite im Café or Ich studiere. Studieren usually means studying at a university; lernen is learning a subject or skill.~Regular endings are -e, -st, -t, -en, -t, -en for ich, du, er/sie/es, wir, ihr, sie/Sie. Verbs with stems ending in -t or -d often add an extra e to make pronunciation easier: du arbeitest, er arbeitet, ihr arbeitet. Do not say du arbeitst. Other spelling adjustments exist, so use the lesson models.~Haben means “to have”: ich habe, du hast, er/sie/es hat, wir haben, ihr habt, sie/Sie haben. The du and third-person singular forms lose the b. You will use haben for possessions and many fixed expressions: Ich habe Zeit (I have time). Learn haben and sein separately; English “I am” does not always predict the German expression.',
'Was machen Sie beruflich?=What do you do for work? (formal)|Ich bin Ärztin.=I am a doctor.|Du arbeitest im Café.=You work in the café.|Er hat Zeit.=He has time.|Wir haben einen Kurs.=We have a course.|Ihr arbeitet in Berlin.=You (plural) work in Berlin.',
[['Du ___ im Café.','arbeitest','An extra e makes the -t stem pronounceable before -st.',['arbeitst','arbeiten']],['Er ___ Zeit.','hat','The third-person singular of haben is hat.',['hast','haben']],['Say “I am a teacher.”','Ich bin Lehrer.','A profession after sein normally has no ein.',['Ich habe Lehrer.','Ich Lehrer bin.']],['Ihr ___ einen Kurs.','habt','Ihr uses habt; wir and sie use haben.',['hast','hat']]],
'Write a short work profile for yourself or an invented person. Include a job, workplace, city and something you have. Rewrite it using er or sie and check every ending.',
'Ich bin Lehrer. Ich arbeite in Berlin. Ich habe einen Deutschkurs. Er ist Lehrer. Er arbeitet in Berlin. Er hat einen Deutschkurs.',
'Interview yourself about work, using the formal question first. Give answers about two different people, changing ich to er or sie.');
add(2,'Do you like reading?','Yes/no questions, gern and changing vowels',
'A yes/no question starts with the conjugated verb: Lernst du Deutsch? The subject follows. A statement keeps the subject first: Du lernst Deutsch. No extra word like English “do” is needed. Answer Ja, ich lerne Deutsch or Nein. You can then add a short explanation. Read pairs of statements and questions to hear the change in order.~Gern describes enjoyment of an activity: Ich lese gern means I like reading. It is not a verb, so the activity verb still needs its ending. To say you dislike an activity, use nicht gern: Ich spiele nicht gern Fußball. Gern and gerne are both valid. A question such as Was machst du gern? asks what you like doing.~Some common verbs change the stem vowel only with du and er/sie/es: lesen → du liest, er liest; sprechen → du sprichst, er spricht; fahren → du fährst, er fährt. The wir and Sie forms remain lesen, sprechen and fahren. Memorise a compact set: lesen, liest; sprechen, spricht; fahren, fährt. Do not apply a stem change to every person.',
'Liest du gern?=Do you like reading?|Ich lese gern.=I like reading.|Er spricht Deutsch.=He speaks German.|Sprichst du Englisch?=Do you speak English?|Wir fahren nach Berlin.=We are going to Berlin.|Sie spielt nicht gern Fußball.=She does not like playing football.',
[['Turn Du lernst Deutsch into a question.','Lernst du Deutsch?','A yes/no question puts the conjugated verb first.',['Du Deutsch lernst?','Lernen du Deutsch?']],['Er ___ gern.','liest','Lesen changes e to ie with er: liest.',['lest','lesen']],['Wir ___ Englisch.','sprechen','The stem change occurs with du and er, not wir.',['spricht','sprichst']],['Say that you like playing.','Ich spiele gern.','Gern modifies the activity; spiele is the conjugated verb.',['Ich gern spielen.','Ich bin spiele.']]],
'Write three activities you enjoy and one you do not. Turn each into a yes/no question for a friend. Answer them using a full sentence.',
'Ich lese gern. Liest du gern? Ja, ich lese gern. Ich spiele gern Fußball. Spielst du gern Fußball? Ich fahre nicht gern Auto. Fährst du gern Auto?',
'Ask and answer four hobby questions. First read them, then cover the text. Include one polite negative answer.');
add(3,'What is that building?','Ein, eine and kein',
'The indefinite article introduces something new: ein Bahnhof (a station), eine Schule (a school), ein Hotel (a hotel). Masculine and neuter share ein in this subject form; feminine uses eine. There is no ordinary indefinite plural article: Das sind Hotels means those are hotels. Once a thing is known, you can use the definite article: Das Hotel ist klein.~To negate a noun with an indefinite article, replace ein with kein: Das ist kein Hotel. Feminine uses keine: Das ist keine Bank. Plural also uses keine here: Das sind keine Schulen. Kein can also negate a noun with no article: Ich habe keine Zeit. Think of it as “not a” or “no”, depending on the sentence.~Nicht usually negates an adjective, verb or other specific information rather than replacing ein. Compare Das ist kein Hotel (the thing is not a hotel) and Das Hotel ist nicht groß (the hotel exists, but is not big). Learn those contrasts instead of translating every English “not” with one word. Nouns after sein use the basic subject-form articles at this level.',
'Das ist ein Bahnhof.=That is a train station.|Das ist eine Schule.=That is a school.|Das ist kein Hotel.=That is not a hotel.|Das sind keine Banken.=Those are not banks.|Das Hotel ist nicht groß.=The hotel is not big.|Ist das eine Apotheke?=Is that a pharmacy?',
[['Das ist ___ Schule.','eine','Schule is feminine: eine Schule.',['ein','einen']],['Das ist ___ Hotel. (not a)','kein','Hotel is neuter; negate ein Hotel with kein Hotel.',['keine','nicht ein']],['Das sind ___ Banken. (no)','keine','Plural negation in this form is keine.',['kein','keinen']],['Das Hotel ist ___ groß.','nicht','Negate the adjective groß with nicht.',['kein','keine']]],
'Draw or imagine six city buildings. Label each with an indefinite article, then correct three false labels using kein or keine. Add two adjective sentences with nicht.',
'Das ist ein Hotel. Das ist eine Schule. Das ist keine Bank. Das ist kein Museum. Das Hotel ist nicht klein. Die Schule ist nicht groß.',
'Pretend someone points to the wrong building. Correct them kindly: Nein, das ist kein … Say what it really is.');
add(3,'Left, right, straight ahead','Formal commands and direction phrases',
'For polite instructions to an adult stranger, use the infinitive-shaped verb followed by Sie: Gehen Sie! (Go!), Warten Sie! (Wait!). This is the formal imperative. With bitte, the request becomes softer: Gehen Sie bitte geradeaus. The special formal imperative of sein is Seien Sie, but most direction tasks use regular forms.~Useful direction chunks are geradeaus (straight ahead), links (left), rechts (right), dann (then), hier (here) and dort (there). Listen for these before trying to understand every word. A direction may be split into several simple commands: Gehen Sie geradeaus. Gehen Sie dann rechts. German rights and lefts can occur without an extra word for “turn” in these beginner instructions.~Start by getting attention: Entschuldigung. Ask Wo ist der Bahnhof? or Wo ist die Apotheke? If you do not understand, ask Noch einmal, bitte. Repeat the key directions to check: Geradeaus und dann links? Saying what you understood gives the other person an easy chance to correct you. Finish with Vielen Dank.',
'Entschuldigung, wo ist der Bahnhof?=Excuse me, where is the station?|Gehen Sie geradeaus.=Go straight ahead.|Gehen Sie dann links.=Then go left.|Warten Sie bitte hier.=Please wait here.|Sprechen Sie bitte langsam.=Please speak slowly.|Vielen Dank!=Thank you very much!',
[['Choose the polite instruction.','Gehen Sie geradeaus.','Formal commands use verb + Sie.',['Sie gehen geradeaus?','Geh du Sie.']],['What does rechts mean?','right','Rechts is right; links is left.',['left','straight ahead']],['Ask someone to wait here politely.','Warten Sie bitte hier.','Verb first, then Sie; bitte adds politeness.',['Sie hier warten bitte.','Wartest Sie hier.']],['Which word helps sequence directions?','dann','Dann means then and introduces the next step in a route.',['kein','wer']]],
'Sketch a route with four stages. Write instructions with Sie. Add an opening question and a request to repeat. Follow your written directions on the sketch to check them.',
'Entschuldigung, wo ist das Hotel? Gehen Sie geradeaus. Gehen Sie dann rechts. Gehen Sie dann links. Warten Sie bitte hier. Noch einmal, bitte.',
'Give the route while tracing it with your finger. Repeat it more slowly, as if helping a visitor.');
add(3,'A small café, a big city','Descriptions, pronoun reference and subject agreement',
'An adjective after sein describes a person or thing: Der Bahnhof ist groß. Die Straße ist lang. Das Café ist klein. In this position, the adjective does not get an ending based on gender. A plural sentence also keeps the adjective unchanged: Die Hotels sind teuer. You will meet adjective endings before nouns later; keep the simpler sein pattern for now.~Replace a previously named noun with a pronoun that matches its grammatical gender: der Bahnhof → er; die Straße → sie; das Café → es. This means German “it” may be er, sie or es. Do not automatically choose es for every object. In the plural, use sie and a plural verb: Die Cafés sind klein. Sie sind schön.~Use aber to contrast two descriptions: Die Stadt ist groß, aber ruhig. Use und to add: Das Café ist klein und schön. A question such as Wie ist das Hotel? asks what the hotel is like, while Wo ist das Hotel? asks its location. Read the question word carefully before choosing an answer.',
'Der Bahnhof ist groß. Er ist hier.=The station is big. It is here.|Die Straße ist lang. Sie ist schön.=The street is long. It is beautiful.|Das Café ist klein. Es ist ruhig.=The café is small. It is quiet.|Die Hotels sind teuer.=The hotels are expensive.|Wie ist die Stadt?=What is the city like?|Wo ist die Stadt?=Where is the city?',
[['Das Café ist klein. ___ ist schön.','Es','Café is neuter, so use es.',['Er','Sie']],['Die Hotels ___ teuer.','sind','Hotels is plural; sein becomes sind.',['ist','bin']],['Ask what a city is like.','Wie ist die Stadt?','Wie asks for a description; wo asks for location.',['Wo ist die Stadt?','Wer ist die Stadt?']],['Die Straße ist ___.','lang','After sein, adjectives keep their basic form.',['lange','langen']]],
'Describe four places, then replace each noun with a pronoun in the next sentence. Include one contrast with aber and one plural sentence.',
'Das Café ist klein. Es ist schön. Der Bahnhof ist groß. Er ist hier. Die Straße ist lang, aber ruhig. Die Hotels sind teuer.',
'Describe your imagined city in five sentences. Ask yourself a Wie question and a Wo question and give different kinds of answers.');
add(3,'Getting there','Transport and present-tense sentence position',
'Use gehen for going on foot and fahren for travelling by vehicle. Ich gehe means I go or I am walking; Ich fahre means I travel or I am going by vehicle. To name transport, learn chunks: mit dem Bus, mit der Bahn, mit dem Auto, mit dem Fahrrad. The changed articles follow mit; you will study the dative system in a later unit.~The conjugated verb stays in second position in an ordinary statement even when time or place comes first: Heute fahre ich mit dem Bus. The entire word Heute occupies the first position, so ich comes after the verb. Do not write Heute ich fahre. You can move a whole phrase such as Am Montag to the first position and still keep the verb second.~Fahren changes its vowel for du and er/sie/es: du fährst, er fährt. Gehen does not: du gehst, er geht. Wohin asks about a destination, whereas wo asks about a location. For cities, use nach: nach Berlin. Practice first with familiar destination names, then add time and transport. A short accurate sentence is enough.',
'Ich fahre mit dem Bus.=I travel by bus.|Heute fahre ich nach Berlin.=Today I am going to Berlin.|Er fährt mit dem Auto.=He travels by car.|Wir gehen zu Fuß.=We go on foot.|Wohin fährst du?=Where are you going?|Am Montag fahre ich mit der Bahn.=On Monday I travel by train.',
[['Heute ___ ich nach Berlin.','fahre','The conjugated verb remains second after Heute.',['ich fahre','fahren']],['Er ___ mit dem Auto.','fährt','Fahren changes a to ä for er.',['fahrt','fahren']],['Which question asks for a destination?','Wohin?','Wohin asks where to; wo asks where.',['Wo?','Wer?']],['Travel to Berlin: ___ Berlin.','nach','Use nach with a city destination.',['aus','um']]],
'Write four journeys with a day, transport and destination. Begin two with ich and two with a time phrase. Underline the conjugated verb in second position.',
'Ich fahre nach Berlin. Heute fahre ich mit dem Bus. Am Montag fahre ich mit der Bahn. Wir gehen zu Fuß.',
'Explain how you travel to three places. Say each sentence once with ich first and once with heute first.');
add(4,'At the bakery','The accusative: a noun’s job in a sentence',
'A subject is the person or thing doing an action. A direct object is what the action affects. In Ich kaufe einen Apfel, ich is the subject and einen Apfel is what I buy. German often shows this difference with article forms. The basic subject form is called nominative; the direct-object form is called accusative. Do not try to learn every case at once.~In the accusative, masculine der becomes den and ein becomes einen. Feminine die/eine and neuter das/ein stay the same. Plural die also stays die. Compare Der Apfel ist rot with Ich kaufe den Apfel. For buying an unspecified apple, say einen Apfel. Common verbs taking a direct object here are kaufen, haben, brauchen, essen and trinken.~Kein follows the same pattern: Ich habe keinen Apfel, keine Banane, kein Brot. The ending is controlled by the noun’s gender and its role, not by the speaker’s gender. Build a sentence in three steps: choose the verb, identify what you buy or need, then check the noun’s article. A little slower now saves repeated guessing later.',
'Ich kaufe einen Apfel.=I am buying an apple.|Ich brauche eine Banane.=I need a banana.|Er hat ein Brot.=He has a loaf of bread.|Wir kaufen den Käse.=We are buying the cheese.|Ich habe keinen Kaffee.=I have no coffee.|Der Apfel ist rot.=The apple is red.',
[['Ich kaufe ___ Apfel.','einen','Apfel is masculine and the direct object: einen Apfel.',['ein','eine']],['Ich brauche ___ Brot.','ein','Brot is neuter; ein does not change in the accusative.',['einen','eine']],['Wir kaufen ___ Käse. (the)','den','Masculine der becomes den for a direct object.',['der','das']],['Ich habe ___ Kaffee. (no)','keinen','Masculine accusative negation uses keinen.',['kein','keine']]],
'Make a shopping list of eight items. Turn it into sentences with ich brauche and ich kaufe. Mark each masculine direct object and check for einen, den or keinen.',
'Ich brauche einen Apfel, eine Banane und ein Brot. Ich kaufe den Käse. Ich brauche keine Milch. Ich habe keinen Kaffee.',
'Role-play buying breakfast. Name five items with their correct articles, then say two things you do not need.');
add(4,'What would you like?','Mögen, möchten and polite ordering',
'Mögen expresses liking: ich mag, du magst, er/sie/es mag, wir mögen, ihr mögt, sie/Sie mögen. You can use it with a food or drink: Ich mag Tee. For enjoying an activity, the gern pattern is especially useful: Ich trinke gern Tee. Do not confuse mögen with möchten: they are related, but they perform different jobs in a beginner conversation.~Möchten means “would like” in polite requests: ich möchte, du möchtest, er/sie/es möchte, wir möchten, ihr möchtet, sie/Sie möchten. It can take a noun directly: Ich möchte einen Kaffee. With another verb, the infinitive goes at the end: Ich möchte einen Kaffee trinken. The möchte form carries the person ending.~In a café, polite fragments are common: Einen Kaffee, bitte. Mit Milch? Ohne Zucker. You can ask Was möchten Sie? and request the bill with Die Rechnung, bitte. Möchten is more courteous than a blunt Ich will in many service encounters. Practise both the full sentence and the short ordering phrase so you can recognise either in a reply.',
'Ich mag Tee.=I like tea.|Ich möchte einen Tee.=I would like a tea.|Was möchten Sie?=What would you like? (formal)|Wir möchten etwas essen.=We would like to eat something.|Einen Kaffee, bitte.=A coffee, please.|Die Rechnung, bitte.=The bill, please.',
[['Politely request a coffee.','Ich möchte einen Kaffee.','Möchte expresses would like; Kaffee is masculine accusative.',['Ich mag ein Kaffee.','Ich möchten Kaffee.']],['Er ___ Tee. (likes)','mag','The er form of mögen is mag.',['mögen','magst']],['Wir möchten etwas ___.','essen','With möchten, the second verb is an infinitive at the end.',['isst','esst']],['Ask for the bill.','Die Rechnung, bitte.','Rechnung is the bill; ask politely with Die Rechnung, bitte.',['Der Bahnhof, bitte.','Guten Morgen, bitte.']]],
'Write a café exchange with four turns: greeting, order, follow-up question and bill request. Make a second version with a different food preference.',
'Guten Tag! Ich möchte einen Kaffee und ein Brötchen. Mit Milch? Ja, bitte. Ich möchte auch etwas essen. Die Rechnung, bitte.',
'Play both customer and server. Ask Was möchten Sie?, order politely, ask a price and thank the server.');
add(4,'A kilo of apples','Quantities, containers and shopping questions',
'German shopping uses measures and containers: ein Kilo Kartoffeln, ein Liter Milch, eine Flasche Wasser, ein Stück Käse. The measure word determines the article in phrases like eine Flasche. Kilo and Liter normally stay unchanged after a number in ordinary quantity expressions: zwei Kilo, drei Liter. The food may follow without an article.~Wie viel asks about an amount or price: Wie viel kostet das? Wie viel Milch brauchen wir? Wie viele asks for a count of plural things: Wie viele Äpfel brauchen wir? The answer can be a digit and noun: vier Äpfel. Notice the difference between asking the price of one item and several: Was kostet das Brot? Was kosten die Äpfel?~German price notation uses a comma: 2,80 €. You may hear zwei Euro achtzig or simply zwei achtzig. To check, repeat the full amount. Grocery shopping is a good place to use bitte and danke. Write a list before speaking, but practise a second round without it. Combine quantities with the accusative: Ich brauche eine Flasche Wasser.',
'Ich brauche ein Kilo Kartoffeln.=I need a kilo of potatoes.|Eine Flasche Wasser, bitte.=A bottle of water, please.|Wie viel kostet das Brot?=How much does the bread cost?|Wie viele Äpfel brauchen wir?=How many apples do we need?|Die Äpfel kosten drei Euro.=The apples cost three euros.|Ich kaufe zwei Liter Milch.=I am buying two litres of milk.',
[['Ask how many apples.','Wie viele Äpfel?','Countable plural things use wie viele.',['Wie viel Äpfel?','Wie alt Äpfel?']],['Ask how much milk.','Wie viel Milch?','Milk is an amount here, so use wie viel.',['Wie viele Milch?','Wie heißt Milch?']],['Die Äpfel ___ drei Euro.','kosten','A plural subject uses kosten.',['kostet','kostest']],['Two kilos: zwei ___.','Kilo','Kilo remains unchanged in this quantity phrase.',['Kilosse','Kilen']]],
'Plan ingredients for two meals with quantities. Write three price questions and answer them using invented euro amounts. Add up your total separately to check that you understood the numbers.',
'Ich brauche ein Kilo Kartoffeln, zwei Liter Milch und vier Äpfel. Was kostet das Brot? Das Brot kostet drei Euro. Was kosten die Äpfel? Die Äpfel kosten zwei Euro.',
'Read your shopping list to a shop assistant, one quantity at a time. Ask them to repeat a price and repeat it back.');
add(4,'At the table','Food preferences, irregular essen and negation',
'Essen means to eat: ich esse, du isst, er/sie/es isst, wir essen, ihr esst, sie/Sie essen. Compare it carefully with sein: ist (is) has one s; isst (eats) has two. They sound alike, so context matters. Trinken follows the regular pattern: ich trinke, du trinkst, er trinkt. Use gern and nicht gern to talk about your own preferences.~Negate a food noun with kein when it has no article or an indefinite article: Ich esse kein Fleisch. Ich trinke keinen Kaffee. Negate an activity or description with nicht: Ich koche nicht. Das Essen ist nicht teuer. To contrast a specific choice, nicht can stand directly before it: Ich trinke nicht Tee, sondern Wasser. At this stage, practise the common full phrases before analysing every placement.~A dietary preference can be stated simply: Ich esse vegetarisch. If you need to ask about an ingredient, say Ist da Milch drin? This unit teaches the language of a question, not a guarantee about a meal’s ingredients. To keep a conversation going, add Und du? Give a full answer once, then practise a shorter natural response.',
'Er isst gern Reis.=He likes eating rice.|Ich esse kein Fleisch.=I do not eat meat.|Sie trinkt keinen Kaffee.=She does not drink coffee.|Das Essen ist nicht teuer.=The food is not expensive.|Ist da Milch drin?=Is there milk in it?|Ich esse vegetarisch.=I eat vegetarian food.',
[['Er ___ gern Reis.','isst','Essen changes to isst with er; ist means is.',['ist','esst']],['Ich esse ___ Fleisch.','kein','Fleisch is neuter and is negated as a noun.',['nicht','keinen']],['Das Essen ist ___ teuer.','nicht','Use nicht to negate an adjective.',['kein','keine']],['Sie ___ Wasser.','trinkt','The regular third-person ending is -t.',['trinken','trinkst']]],
'Write a food diary for one day. Say what you eat and drink, two preferences and one thing you do not eat. Ask one ingredient question.',
'Ich esse gern Brot. Ich trinke Tee. Mittags esse ich Reis. Ich esse kein Fleisch. Ich trinke keinen Kaffee. Ist da Milch drin?',
'Describe breakfast, lunch and dinner. Ask an imaginary friend about their preferences and respond with your own.');
add(5,'What time is it?','Clock time and am, um, von … bis',
'For precise schedules, use the 24-hour clock: vierzehn Uhr dreißig is 14:30. For daily conversation, you may hear halb drei, which means half past two, literally halfway to three. This differs from English “half three” in places where that means 3:30. Viertel nach zwei is 2:15; Viertel vor drei is 2:45. Regional forms vary; the 24-hour version is a safe clear choice.~Um introduces an exact clock time: um neun Uhr. Am introduces a weekday or part of the day: am Montag, am Morgen, am Abend. An exception is in der Nacht. Von … bis gives a time span: von neun bis fünf. To ask when an event happens, say Wann beginnt der Kurs? To ask the current time, use Wie spät ist es?~Practise converting between written digits and spoken phrases. Do not merely recognise a clock: say a complete sentence with the time. Include the day if arranging something. Confirm ambiguous times by repeating them in 24-hour form. Halb neun in a morning work routine means 8:30; the same phrase without context could mean morning or evening.',
'Es ist halb neun.=It is half past eight.|Es ist Viertel nach zwei.=It is quarter past two.|Der Kurs beginnt um neun Uhr.=The course starts at nine.|Ich arbeite am Montag.=I work on Monday.|Ich arbeite von neun bis fünf.=I work from nine to five.|Wie spät ist es?=What time is it?',
[['What time is halb neun?','8:30','Halb names the coming hour: halfway to nine.',['9:30','9:00']],['Der Kurs beginnt ___ neun Uhr.','um','An exact clock time takes um.',['am','in']],['Ich arbeite ___ Montag.','am','Weekdays take am; an exact clock time instead takes um.',['um','aus']],['Viertel vor drei means ___.','2:45','A quarter before three is 2:45.',['3:15','3:45']]],
'Write six times in digits and German. Add a weekday schedule with three appointments and one from–to time span. Confirm each half-hour phrase by converting it back to digits.',
'8:30: halb neun. 14:15: vierzehn Uhr fünfzehn. Am Montag beginnt der Kurs um neun Uhr. Ich arbeite von zehn bis fünf. Um sechs Uhr esse ich.',
'Read a day’s schedule as a voice message. State every time clearly in 24-hour form, then repeat two times conversationally.');
add(5,'From morning to night','Separable verbs and the sentence frame',
'Some German verbs have a prefix that separates in an ordinary present-tense statement: aufstehen (get up) → Ich stehe um sieben Uhr auf. The conjugated part stays in second position and the prefix moves to the end. This creates a frame around the rest of the information. Other useful verbs are einkaufen, anrufen, anfangen and mitbringen.~Questions keep the same end position for the prefix: Wann stehst du auf? Rufst du mich an? The verb anfangen also changes its vowel: du fängst an, er fängt an. Separate the two questions in your mind: which ending or stem does the person need, and where does the prefix go? With ich and wir, anfangen has no vowel change.~When a modal verb is present, the infinitive stays whole at the end: Ich muss früh aufstehen. Do not split it again after müssen. Not every verb with a beginning syllable separates; besuchen, for example, does not. Learn a separable verb with one example sentence so the pattern becomes familiar. In listening, wait for the end of the sentence before deciding exactly which action was meant.',
'Ich stehe um sieben Uhr auf.=I get up at seven.|Er fängt um neun Uhr an.=He starts at nine.|Wir kaufen heute ein.=We are shopping today.|Rufst du mich an?=Will you call me?|Ich bringe Brot mit.=I am bringing bread along.|Ich muss früh aufstehen.=I have to get up early.',
[['Ich ___ um sieben Uhr auf.','stehe','Aufstehen separates: stehe … auf.',['aufstehe','stehen']],['Er ___ um neun Uhr an.','fängt','Anfangen changes a to ä for er.',['fangt','fangen']],['With muss, use ___.','Ich muss früh aufstehen.','After a modal, the full infinitive goes at the end.',['Ich muss stehe früh auf.','Ich aufstehen muss früh.']],['Complete: Wir kaufen heute ___.','ein','Einkaufen separates into kaufen … ein.',['an','auf']]],
'Write a six-action daily routine using at least four separable verbs. Circle each prefix at the end. Rewrite two sentences with a time phrase first.',
'Ich stehe um sieben Uhr auf. Um acht Uhr fange ich an. Ich kaufe am Abend ein. Ich rufe meine Mutter an. Ich bringe Brot mit.',
'Describe your day from getting up to evening. Pause briefly before the final prefix if needed, but do not omit it.');
add(5,'I can, I must, I want','Modal verbs and infinitives',
'A modal verb changes the meaning of another action: können is ability or possibility, müssen is necessity and wollen is a strong intention. Learn the singular forms together: ich kann, du kannst, er kann; ich muss, du musst, er muss; ich will, du willst, er will. The ich and er forms match. Plurals are wir können/müssen/wollen and ihr könnt/müsst/wollt.~The modal is conjugated and placed where the main verb would normally go. The action is an infinitive at the end: Ich kann heute kommen. In a question, the modal can move first: Kannst du heute kommen? Do not conjugate both verbs. For a separable action, keep the infinitive together: Ich muss einkaufen.~Negation changes meaning in an important way. Ich muss nicht arbeiten means I do not have to work; it does not mean I am forbidden to work. Ich kann nicht kommen means I cannot come. Wollen can sound direct in a request; for a polite order, use möchten. Practise personal plans with wollen and requests with können or möchten.',
'Ich kann Deutsch sprechen.=I can speak German.|Du musst heute arbeiten.=You have to work today.|Er will nach Berlin fahren.=He wants to go to Berlin.|Können Sie morgen kommen?=Can you come tomorrow? (formal)|Ich muss nicht arbeiten.=I do not have to work.|Wir wollen einkaufen.=We want to go shopping.',
[['Ich ___ heute kommen. (can)','kann','The ich form is kann; kommen stays infinitive.',['können','kannst']],['Du ___ arbeiten. (must)','musst','Du uses musst; the ich and er forms are muss without -t.',['muss','müssen']],['Ich muss nicht arbeiten means ___.','I do not have to work.','Nicht müssen removes an obligation; it does not forbid.',['I must not work.','I cannot work.']],['Choose the correct frame.','Er will nach Berlin fahren.','The modal is conjugated; fahren closes the sentence.',['Er will fährt nach Berlin.','Er fahren will Berlin.']]],
'Write two things you can do, two things you must do and two things you want to do. Add one thing you do not have to do. Underline the final infinitives.',
'Ich kann Deutsch lesen. Ich kann kochen. Ich muss arbeiten. Ich muss einkaufen. Ich will nach Berlin fahren. Ich muss am Sonntag nicht arbeiten.',
'Explain tomorrow’s plans with kann, muss and will. Ask another person whether they can join you.');
add(5,'Let’s find a time','Appointments and polite rescheduling',
'A successful appointment conversation contains the purpose, day, time and a confirmation. Start with Ich möchte einen Termin or Können wir einen Termin machen? Ask Wann haben Sie Zeit? Use am with the day and um with the hour. It is normal to repeat the agreed details: Also am Mittwoch um zehn Uhr. Also here means “so” or “then”, not English “also”.~If you cannot accept, say Leider kann ich am Mittwoch nicht. Leider means unfortunately and softens the refusal. Offer an alternative: Geht es am Donnerstag? (Does Thursday work?). In a sentence beginning with leider, the conjugated verb still comes second: Leider kann ich nicht kommen. The infinitive kommen remains at the end.~For lateness, say Entschuldigung, ich komme zehn Minuten später. A short message should identify you because the listener may not recognise your voice. Before a phone call, write a few key phrases and two possible times. You do not need a long explanation. The aim is to agree the same time and place, so verify those details aloud at the end.',
'Ich möchte einen Termin.=I would like an appointment.|Wann haben Sie Zeit?=When do you have time? (formal)|Leider kann ich nicht kommen.=Unfortunately I cannot come.|Geht es am Donnerstag?=Does Thursday work?|Also am Mittwoch um zehn Uhr.=So, on Wednesday at ten.|Ich komme zehn Minuten später.=I will arrive ten minutes later.',
[['Leider ___ ich nicht kommen.','kann','With Leider first, the conjugated modal still occupies second position.',['ich kann','können']],['Use the right day-and-time phrase.','am Mittwoch um zehn Uhr','Am marks the day; um marks the clock time.',['um Mittwoch am zehn Uhr','in Mittwoch aus zehn Uhr']],['Ask whether Thursday works.','Geht es am Donnerstag?','This is a common scheduling question.',['Woher ist Donnerstag?','Wie heißt zehn?']],['Ten minutes later: zehn Minuten ___.','später','Später means later; zehn Minuten später gives the amount of delay.',['früh','gestern']]],
'Write a short message cancelling an appointment. Give your name, offer a new day and time, and ask for confirmation. Then write a separate one-sentence lateness message.',
'Guten Tag, hier ist Sami Ali. Leider kann ich am Mittwoch nicht kommen. Geht es am Donnerstag um zehn Uhr? Vielen Dank. Entschuldigung, ich komme zehn Minuten später.',
'Leave a 30-second appointment message. Replay it and check that your name, date and time are understandable.');
add(6,'Meet my family','Possessive articles in nominative and accusative',
'Possessive articles show a relationship: mein (my), dein (your, familiar), sein (his/its), ihr (her/their), unser (our), euer (your, familiar plural) and Ihr (your, formal). The beginning identifies the owner; the ending matches the noun and its grammatical role. Mein Vater and meine Mutter are both possible regardless of who is speaking.~In the basic subject form, use mein Vater, meine Mutter, mein Kind and meine Eltern. In the accusative masculine, add -en: Ich besuche meinen Vater. Feminine, neuter and plural look the same as their subject forms in these examples: meine Mutter, mein Kind, meine Eltern. Other possessives mostly follow this pattern. Euer becomes eure before a feminine or plural noun: eure Mutter, eure Kinder.~Do not choose sein or ihr from the gender of the possession. Choose it from the owner: Mira → ihr Vater; Sami → sein Vater. Both possessions are masculine Vater, but the owner changes the beginning. Build a small family tree and write one sentence per link. A grammatical category and a real family relationship are different kinds of information.',
'Das ist mein Vater.=That is my father.|Meine Mutter wohnt in Kairo.=My mother lives in Cairo.|Ich besuche meinen Bruder.=I am visiting my brother.|Mira und ihr Vater sind hier.=Mira and her father are here.|Sami und seine Mutter kommen.=Sami and his mother are coming.|Sind das Ihre Kinder?=Are those your children? (formal)',
[['Ich besuche ___ Vater. (my)','meinen','Vater is masculine direct object, so mein becomes meinen.',['mein','meine']],['___ Mutter ist hier. (my)','Meine','Mutter is feminine: meine Mutter.',['Mein','Meinen']],['Mira and her father: Mira und ___ Vater.','ihr','The owner Mira determines ihr, not the gender of Vater.',['sein','ihre']],['Formal “your children”: ___ Kinder.','Ihre','Formal possessive Ihr is capitalised, with -e for plural here.',['dein','Ihren']]],
'Draw an actual or fictional family tree. Write six sentences, including possessions or relationships for two different owners. Use one masculine accusative after besuchen.',
'Das ist meine Mutter. Mein Vater wohnt in Kairo. Ich besuche meinen Bruder. Mira besucht ihre Mutter. Sami besucht seinen Vater. Unsere Kinder sind hier.',
'Introduce four family members or invented people. Say one fact about each and use sein or ihr to connect two people.');
add(6,'Save the date','Ordinal numbers, months and birthdays',
'Cardinal numbers count things: eins, zwei, drei. Ordinal numbers put things in order: erste, zweite, dritte. Dates use ordinals. For “on” a date, learn am plus an -en form: am ersten Mai, am zweiten Juni, am dritten Juli. From four to nineteen, most use -ten: am vierten, am zehnten. Important exceptions include ersten, dritten, siebten and achten.~From twenty onward, use -sten: am zwanzigsten, am einundzwanzigsten. A written dot after a date number signals an ordinal: am 3. Mai. German numeric dates normally give day before month: 03.05. means 3 May, not March 5. To name today’s date as a subject complement, use Heute ist der dritte Mai. Keep that distinct from am dritten Mai.~Use im with a month alone: im Mai. Use am with the actual day/date: am dritten Mai. A birthday question is Wann hast du Geburtstag? A short answer can be Am dritten Mai. Learn the months in order, then practise random ones so you are not dependent on reciting the entire list each time.',
'Ich habe am dritten Mai Geburtstag.=My birthday is on May third.|Heute ist der dritte Mai.=Today is May third.|Die Party ist am einundzwanzigsten Juni.=The party is on June twenty-first.|Im Januar ist es kalt.=It is cold in January.|Wann hast du Geburtstag?=When is your birthday?|Am ersten August habe ich Zeit.=I have time on August first.',
[['On May third: am ___ Mai.','dritten','Am takes the date form dritten.',['drei','dritte']],['German 03.05. means ___.','3 May','Numeric dates put day before month.',['5 March','May 30']],['___ Januar ist es kalt.','Im','Use im with a month without a specific day.',['Am','Um']],['On the twenty-first: am ___.','einundzwanzigsten','Ordinals from twenty use -st-, plus the ending -en after am.',['einundzwanzigten','einsundzwanzig']]],
'Create a calendar with five events. Write dates in digits and words, and include the time for three events. Add two birthday questions with answers.',
'Am dritten Mai habe ich Geburtstag. Die Party ist am vierten Mai um sechs Uhr. Am einundzwanzigsten Juni habe ich Zeit. Wann hast du Geburtstag?',
'Invite someone to two calendar events. Say each date clearly, then repeat the date using the month name.');
add(6,'You’re invited','Accusative pronouns, für and invitations',
'Direct-object pronouns replace people or things affected by an action. The common forms are mich (me), dich (you, familiar singular), ihn (him/masculine it), sie (her/feminine it), es (neuter it), uns (us), euch (familiar plural you), sie (them) and Sie (formal you). Compare Ich besuche meinen Bruder with Ich besuche ihn.~Für means for and takes the accusative: für meinen Bruder, für meine Mutter, für dich. The form does not change just because the English phrase feels indirect. German prepositions can determine case themselves. Einladen is separable: Ich lade dich ein. Mitbringen is also separable: Bring bitte etwas mit, or formally Bringen Sie bitte etwas mit.~A usable invitation gives an occasion, date, time, place and what the other person should do. Keep each item in a short sentence. To accept, say Ja, gern! To refuse politely, say Danke für die Einladung. Leider habe ich keine Zeit. You can still offer an alternative. Read your invitation as if you knew nothing about the event: could you actually attend from the information provided?',
'Ich lade dich ein.=I am inviting you.|Das Geschenk ist für ihn.=The gift is for him.|Wir besuchen sie.=We are visiting her / them.|Danke für die Einladung.=Thank you for the invitation.|Leider habe ich keine Zeit.=Unfortunately I have no time.|Bring bitte etwas mit.=Please bring something along.',
[['Ich lade ___ ein. (you, familiar singular)','dich','Dich is the direct-object form of du.',['du','dir']],['For my brother: für ___ Bruder.','meinen','Für takes accusative; masculine mein becomes meinen.',['mein','meinem']],['Das Geschenk ist für ___. (him)','ihn','Für uses the accusative pronoun ihn.',['er','ihm']],['Politely refuse an invitation.','Leider habe ich keine Zeit.','This expresses regret and lack of time.',['Ich bin keine Zeit.','Leider ich haben Zeit.']]],
'Write an invitation of 30–40 words with occasion, date, time, place and a request. Then write a short acceptance and a refusal.',
'Hallo Nora, ich habe am dritten Mai Geburtstag. Die Party ist am Samstag um sechs Uhr bei mir. Ich lade dich ein. Bring bitte etwas zu trinken mit. Hast du Zeit? Viele Grüße, Sami',
'Read the invitation naturally, then respond as the friend. Practise accepting once and declining once.');
add(6,'How was yesterday?','The simple past of sein and haben',
'German often uses war and hatte to talk about a past state or possession, even in everyday speech. Sein becomes ich war, du warst, er/sie/es war, wir waren, ihr wart, sie/Sie waren. Haben becomes ich hatte, du hattest, er/sie/es hatte, wir hatten, ihr hattet, sie/Sie hatten. These are simple-past forms, called Präteritum.~Use war for a state, description or location: Ich war müde; Wir waren in Berlin. Use hatte for possession and fixed expressions with haben: Ich hatte keine Zeit; Sie hatte Hunger. English may tempt you to translate “was hungry” with war, but German says hatte Hunger. Learn the full expression in both present and past.~A past time phrase such as gestern still takes one first-position slot: Gestern war ich krank. The verb remains second, and the subject follows it. Use aber to contrast then and now: Gestern war ich müde, aber heute bin ich fit. You do not need the past tense of every German verb yet; these two let you talk about many everyday experiences.',
'Gestern war ich krank.=Yesterday I was ill.|Wir waren in Berlin.=We were in Berlin.|Ich hatte keine Zeit.=I had no time.|Hattest du Hunger?=Were you hungry?|Heute bin ich fit.=Today I am fit / feeling well.|Ihr wart im Café.=You (plural) were in the café.',
[['Gestern ___ ich krank.','war','A past state uses war, the past of sein.',['hatte','bin']],['Ich ___ keine Zeit. (past)','hatte','Zeit is used with haben; its past form is hatte.',['war','waren']],['Wir ___ in Berlin.','waren','Wir takes the plural past form waren.',['war','wart']],['Du ___ Hunger. (past)','hattest','Du uses hattest. Hunger is expressed with haben.',['hatte','warst']]],
'Write five sentences about yesterday and three about today. Use both war and hatte, then contrast past and present with aber.',
'Gestern war ich müde. Ich hatte keine Zeit. Wir waren im Café. Ich hatte Hunger. Heute bin ich fit. Heute habe ich Zeit.',
'Give a short yesterday-versus-today report. Listen to your recording and check war/hatte and bin/habe choices.');
add(7,'Come on in','Rooms, es gibt and describing a home',
'Es gibt means there is or there are. German uses the same gibt form for one or several things: Es gibt ein Bad; Es gibt zwei Zimmer. The thing that exists is in the accusative, so masculine nouns use einen: Es gibt einen Balkon. Do not change gibt to geben for plural nouns in this expression.~A home description can combine haben, sein and es gibt: Die Wohnung hat zwei Zimmer. Sie ist hell. Es gibt einen Balkon. Wohnung is feminine, so the pronoun referring to it is sie. An adjective after sein has no gender ending: Die Zimmer sind hell. For counting rooms, ask Wie viele Zimmer hat die Wohnung?~Rental adverts use compact vocabulary such as Miete (rent), Zimmer (room), Quadratmeter (square metre) and frei (available). Warmmiete and Kaltmiete refer to different rent totals; details vary, so ask which costs are included. The language task is to extract the room count, price and contact details rather than infer facts not stated in the advert. Practise with an invented listing before describing a real one.',
'Meine Wohnung hat zwei Zimmer.=My apartment has two rooms.|Es gibt einen Balkon.=There is a balcony.|Es gibt zwei Schlafzimmer.=There are two bedrooms.|Die Küche ist hell.=The kitchen is bright.|Wie viele Zimmer hat die Wohnung?=How many rooms does the apartment have?|Die Miete ist 700 Euro im Monat.=The rent is 700 euros per month.',
[['Es ___ zwei Zimmer.','gibt','Es gibt stays singular even when several things follow.',['geben','sind']],['Es gibt ___ Balkon.','einen','Es gibt takes accusative; Balkon is masculine.',['ein','eine']],['Die Zimmer sind ___.','hell','After sein, the adjective has no added ending.',['helle','hellen']],['Ask for the number of rooms.','Wie viele Zimmer hat die Wohnung?','Use wie viele for countable plural rooms.',['Wie viel Zimmer ist Wohnung?','Woher hat die Wohnung?']]],
'Write a six-sentence advert for an imaginary apartment: city, rooms, rent, two descriptions and one extra feature. Then write two questions a prospective tenant should ask.',
'Die Wohnung ist in Berlin. Sie hat zwei Zimmer. Die Küche ist hell. Es gibt einen Balkon. Die Miete ist 700 Euro im Monat. Wie viele Zimmer hat die Wohnung?',
'Give a short tour: name each room and describe it. End with two questions about another apartment.');
add(7,'Where did I put it?','Location phrases and the dative',
'To describe where something is, German often uses a preposition and the dative case: in der Küche, auf dem Tisch, neben dem Fenster. In these location phrases, masculine der and neuter das become dem; feminine die becomes der. Plural die becomes den, and many plural nouns add -n if they do not already end in -n or -s.~The location question is Wo? You can answer Das Buch liegt auf dem Tisch. The prepositions in, an, auf, unter, über, vor, hinter, neben and zwischen can take two cases. With a location, use dative. With a destination, they can take accusative. Focus on the location use in this lesson rather than changing the case simply because any movement happens.~Useful contractions include in dem → im and an dem → am. A room description may use ist, steht, liegt or hängt: a table stands, a book lies, a picture hangs. Learn these with concrete objects, but remember that natural German sometimes chooses a different verb from English. Imagine a room and point before speaking to make the spatial meaning clear.',
'Das Buch liegt auf dem Tisch.=The book is on the table.|Der Tisch steht in der Küche.=The table is in the kitchen.|Die Lampe steht neben dem Bett.=The lamp is next to the bed.|Das Bild hängt an der Wand.=The picture hangs on the wall.|Ich bin im Bad.=I am in the bathroom.|Der Stuhl steht vor dem Fenster.=The chair is in front of the window.',
[['Das Buch liegt auf ___ Tisch.','dem','Tisch is masculine; a location after auf takes dative dem.',['den','der']],['Der Tisch steht in ___ Küche.','der','Küche is feminine; dative die becomes der.',['die','dem']],['Im is a contraction of ___.','in dem','Im combines in and dem; it is commonly used for a location.',['in den','in die']],['Which question asks location?','Wo?','Wo asks where something is.',['Wohin?','Woher?']]],
'Draw a room and place six objects. Write six location sentences using in, auf, unter, neben, vor or an. Check each noun’s gender before selecting dem or der.',
'Das Buch liegt auf dem Tisch. Der Stuhl steht neben dem Tisch. Das Bett steht im Schlafzimmer. Die Lampe steht neben dem Bett. Das Bild hängt an der Wand.',
'Describe object locations without showing your drawing. Then use your recording to redraw the room and compare.');
add(7,'For me, with you','Dative after mit, bei, zu, aus and von',
'Some prepositions consistently use the dative. For beginner conversations, learn mit (with/by), bei (at someone’s place or workplace), zu (to), aus (from/out of), and von (from/of). Unlike the two-way location prepositions, these do not switch to accusative just because you are going somewhere: Ich fahre mit dem Bus; Ich gehe zu dem Arzt.~Common contractions are zu dem → zum, zu der → zur, bei dem → beim and von dem → vom. Use zur Schule, zum Arzt, beim Arzt, vom Bahnhof. A destination such as zum Arzt and a location such as beim Arzt have different meanings even though both are dative. To go home say nach Hause; to be at home say zu Hause.~Dative personal pronouns include mir (to/for me), dir (to/for you, familiar), ihm (him/it), ihr (her), uns (us), euch (you plural), ihnen (them) and Ihnen (formal you). Practise a few chunks: mit mir, bei dir, von ihm. Case forms become easier when you learn the preposition together with a realistic phrase.',
'Ich fahre mit dem Bus.=I travel by bus.|Ich gehe zum Arzt.=I am going to the doctor.|Sie ist beim Arzt.=She is at the doctor’s.|Wir gehen zur Schule.=We are going to school.|Kommst du mit mir?=Are you coming with me?|Ich bin zu Hause.=I am at home.',
[['Travel by bus: mit ___ Bus.','dem','Mit always takes dative; Bus is masculine.',['den','der']],['Zu der contracts to ___.','zur','Zur combines zu + der; zum instead combines zu + dem.',['zum','vom']],['Are you coming with me? mit ___.','mir','After mit, use the dative pronoun mir.',['mich','ich']],['At home: ___.','zu Hause','Zu Hause is location; nach Hause is destination.',['nach Hause','aus Hause']]],
'Write a route from home to school, a friend’s place and a doctor’s office. Use at least four dative prepositions and two contractions.',
'Ich fahre mit dem Bus zur Schule. Dann gehe ich zu meiner Freundin. Ich bin bei ihr. Am Abend fahre ich nach Hause. Morgen gehe ich zum Arzt.',
'Explain where you are, where you are going and who is coming with you. Practise zu Hause versus nach Hause.');
add(7,'Making a house a home','Location versus destination with in and auf',
'Compare Das Buch liegt auf dem Tisch (the book is on the table) with Ich lege das Buch auf den Tisch (I put the book onto the table). The first describes a location; the second names a destination for the book. Two-way prepositions such as in and auf take dative for location and accusative for destination. The important distinction is where versus where to, not simply stillness versus movement.~For masculine nouns, der becomes dem in dative and den in accusative. For neuter nouns, das becomes dem in dative but stays das in accusative. For feminine nouns, die becomes der in dative but stays die in accusative. In das contracts to ins, while in dem contracts to im. Compare im Wohnzimmer and ins Wohnzimmer.~Useful verb pairs are liegen/legen and stehen/stellen: Das Buch liegt; ich lege das Buch. Der Stuhl steht; ich stelle den Stuhl. These patterns can take time. Keep a physical object nearby and first describe where it is, then move it and describe the destination. Accuracy is more useful than rushing through many examples.',
'Das Buch liegt auf dem Tisch.=The book is on the table.|Ich lege das Buch auf den Tisch.=I put the book on the table.|Der Stuhl steht im Zimmer.=The chair is in the room.|Ich stelle den Stuhl ins Zimmer.=I put the chair into the room.|Ich bin in der Küche.=I am in the kitchen.|Ich gehe in die Küche.=I go into the kitchen.',
[['Ich lege das Buch auf ___ Tisch.','den','The table is the destination; masculine accusative is den.',['dem','der']],['Das Buch liegt auf ___ Tisch.','dem','This describes location; masculine dative is dem.',['den','das']],['In das contracts to ___.','ins','Ins expresses in das, often a destination.',['im','am']],['Ich gehe in ___ Küche.','die','The kitchen is the destination, so use accusative die.',['der','dem']]],
'Write four pairs of sentences showing where an object is and where you put it. Use the same object and destination in each pair so the case contrast is visible.',
'Das Buch liegt auf dem Tisch. Ich lege das Buch auf den Tisch. Der Stuhl steht im Zimmer. Ich stelle den Stuhl ins Zimmer. Ich bin in der Küche. Ich gehe in die Küche.',
'Move a book and describe the movement, then describe its new location. Repeat with a chair or another safe object.');
add(8,'One ticket, please','Travel questions, timetables and separable travel verbs',
'A ticket conversation often begins with a destination and ticket type: Eine Fahrkarte nach Köln, bitte. Einfach means one way; hin und zurück means return. Listen for Abfahrt (departure), Ankunft (arrival), Gleis (platform or track), and Verspätung (delay). A printed or spoken time such as 14:10 is vierzehn Uhr zehn. Check the destination as well as the departure time.~Travel verbs frequently separate: abfahren → Der Zug fährt ab; ankommen → Der Zug kommt an; umsteigen → Ich steige um. Fahren changes its vowel with er, so Der Zug fährt um zehn Uhr ab. A modal keeps the infinitive together: Muss ich umsteigen? Answering that question is often more useful than understanding every word in a long announcement.~To ask about a departure, say Wann fährt der Zug ab? To ask the platform, say Von welchem Gleis fährt der Zug ab? Learn the second as a complete travel phrase for now. Read a timetable by identifying a specific journey first, then its time and platform. If uncertain, confirm with the full destination and time rather than guessing.',
'Eine Fahrkarte nach Köln, bitte.=A ticket to Cologne, please.|Hin und zurück, bitte.=Return, please.|Wann fährt der Zug ab?=When does the train leave?|Der Zug fährt um vierzehn Uhr zehn ab.=The train leaves at 14:10.|Muss ich umsteigen?=Do I have to change trains?|Der Zug kommt um fünf Uhr an.=The train arrives at five.',
[['A return ticket is ___.','hin und zurück','Hin und zurück means out and back.',['einfach','geschlossen']],['Der Zug ___ um zehn Uhr ab.','fährt','The singular subject uses fährt; ab stays at the end.',['fahren','fahrt']],['Ask whether you must change trains.','Muss ich umsteigen?','The modal goes first; the separable infinitive remains whole.',['Ich muss steige um?','Muss um ich steigen?']],['Ankunft means ___.','arrival','Abfahrt is departure; Ankunft is arrival.',['departure','price']]],
'Invent a timetable for three journeys with destination, departure, arrival and platform. Write a six-turn ticket conversation using one journey.',
'Eine Fahrkarte nach Köln, bitte. Einfach oder hin und zurück? Hin und zurück. Wann fährt der Zug ab? Um vierzehn Uhr zehn, von Gleis drei. Muss ich umsteigen? Nein.',
'Act out the ticket conversation without reading. Ask the time and platform again, then repeat them to confirm.');
add(8,'I visited Berlin','The conversational past with haben',
'For many completed actions, everyday German uses the Perfekt, built from a conjugated helper verb and a past participle. With haben, say Ich habe Berlin besucht. Habe takes the normal second position; besucht goes at the end. The participle does not change with the subject: Wir haben Berlin besucht. English translations may use “visited” or “have visited”, depending on context.~Regular participles often follow ge- + stem + -t: machen → gemacht, kaufen → gekauft, lernen → gelernt. Verbs whose stem ends in -t or -d often need -et: arbeiten → gearbeitet. Verbs ending in -ieren have no ge-: telefonieren → telefoniert. Inseparable prefixes such as be- and ver- also block ge-: besuchen → besucht.~In a separable verb, ge appears between prefix and stem: einkaufen → eingekauft. Irregular verbs need their own learned form: essen → gegessen, trinken → getrunken, lesen → gelesen. Do not guess every past form with ge…t. Begin with a small reliable set and a time phrase such as gestern. Ask a question by moving haben first: Hast du Deutsch gelernt?',
'Ich habe Deutsch gelernt.=I studied German.|Wir haben Berlin besucht.=We visited Berlin.|Sie hat im Café gearbeitet.=She worked in the café.|Ich habe eingekauft.=I went shopping.|Er hat Tee getrunken.=He drank tea.|Hast du das Buch gelesen?=Have you read the book?',
[['Ich ___ Deutsch gelernt.','habe','The helper haben is conjugated for ich.',['bin','hat']],['Past participle of besuchen?','besucht','The inseparable be- prefix means no ge- is added.',['gebesucht','besuchen']],['Past participle of einkaufen?','eingekauft','For a separable verb, ge goes after the prefix.',['geeinkauft','eingekaufen']],['Wir haben Tee ___.','getrunken','Trinken has the irregular participle getrunken.',['getrinkt','trinkt']]],
'Write six things you did yesterday using haben + participle. Include one regular verb, one -ieren verb, one separable verb and one irregular verb. Put the participle at the end.',
'Ich habe Deutsch gelernt. Ich habe telefoniert. Ich habe eingekauft. Ich habe Tee getrunken. Ich habe ein Buch gelesen. Ich habe meine Freundin besucht.',
'Give a 45-second report about yesterday. Pause between sentences and check that every one has a helper and a participle.');
add(8,'I arrived yesterday','The conversational past with sein',
'A number of common intransitive verbs of change of place or state use sein in the Perfekt: Ich bin nach Berlin gefahren; Er ist gekommen. Learn the helper with the participle. Useful pairs are gehen → ist gegangen, fahren → ist gefahren, kommen → ist gekommen, aufstehen → ist aufgestanden. Bleiben also uses sein: ist geblieben, even though it does not mean moving.~Conjugate sein normally: ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind. The participle goes at the end: Gestern sind wir nach Köln gefahren. A sentence that begins with gestern still has the helper second. You may combine two short sentences with und, but first make sure each part is complete.~The general motion rule is a useful starting point, not a rule for every possible use of a verb. Practise the specific beginner expressions here. Contrast an action at a destination with the journey: Ich bin nach Berlin gefahren. Ich habe das Museum besucht. Reisen often combines both helpers, so choose the verb and its learned past form before constructing the sentence.',
'Ich bin nach Berlin gefahren.=I travelled to Berlin.|Wir sind gestern angekommen.=We arrived yesterday.|Er ist früh aufgestanden.=He got up early.|Sie ist zu Hause geblieben.=She stayed at home.|Bist du zu Fuß gegangen?=Did you go on foot?|Ich habe das Museum besucht.=I visited the museum.',
[['Ich ___ nach Berlin gefahren.','bin','This journey with fahren uses sein in the Perfekt.',['habe','hat']],['Wir ___ gestern angekommen.','sind','Wir takes sind; ankommen uses sein.',['haben','seid']],['She stayed: Sie ist zu Hause ___.','geblieben','Bleiben uses sein and the participle geblieben.',['gebleibt','bleibt']],['I visited the museum: Ich ___ das Museum besucht.','habe','Besuchen takes haben, unlike the journey verb fahren here.',['bin','ist']]],
'Write a postcard with six past-tense sentences about a trip. Include three journey or arrival statements with sein and three activities with haben. Check the helpers separately.',
'Ich bin nach Köln gefahren. Ich bin am Montag angekommen. Ich habe ein Museum besucht. Ich habe Kaffee getrunken. Ich bin zu Fuß gegangen. Ich habe Deutsch gesprochen.',
'Tell the story of a trip in order: travel, arrival, activity, meal and return. Use both helpers.');
add(8,'Checking in','Hotel requests and travel problem-solving',
'A hotel check-in starts with Ich habe ein Zimmer reserviert, followed by your name. Common room types are ein Einzelzimmer and ein Doppelzimmer. You can ask Ist das Frühstück inklusive? and Wann ist das Frühstück? A clear request names what you need: Ich brauche ein Handtuch. Use Können Sie mir bitte helfen? when you need assistance.~Negation helps report a problem: Der Schlüssel funktioniert nicht; Das Zimmer ist nicht sauber. Do not try to solve a complex complaint with a long sentence. State one fact and make one request. Modal questions with können are polite and reusable. The infinitive stays at the end: Können Sie das bitte wiederholen?~Combine the past and present to explain the situation: Ich bin gestern angekommen. Ich habe ein Zimmer reserviert. Jetzt brauche ich Hilfe. In listening, identify the room number, breakfast time, checkout time and price. Write them down, then ask for confirmation. Hotel vocabulary and practices differ, so confirm rather than assuming a service is included.',
'Ich habe ein Zimmer reserviert.=I have reserved a room.|Ein Einzelzimmer, bitte.=A single room, please.|Ist das Frühstück inklusive?=Is breakfast included?|Ich brauche ein Handtuch.=I need a towel.|Der Schlüssel funktioniert nicht.=The key does not work.|Können Sie mir bitte helfen?=Could you please help me?',
[['Say you have booked a room.','Ich habe ein Zimmer reserviert.','Reservieren forms reserviert without ge-.',['Ich bin ein Zimmer reservieren.','Ich habe gereserviert Zimmer.']],['Ask whether breakfast is included.','Ist das Frühstück inklusive?','Inklusive asks whether it is included.',['Woher Frühstück?','Ist das Gleis Frühstück?']],['The key does not work: funktioniert ___.','nicht','Negate this verb phrase with nicht.',['kein','keine']],['Können Sie mir bitte ___?','helfen','The infinitive follows the conjugated modal at the end.',['hilft','helfe']]],
'Write a hotel dialogue with a reservation, a breakfast question, a room problem and a polite request. Include your name and an invented room number.',
'Guten Tag, ich heiße Sami Ali. Ich habe ein Zimmer reserviert. Ist das Frühstück inklusive? Mein Zimmer ist Nummer zwölf. Der Schlüssel funktioniert nicht. Können Sie mir bitte helfen?',
'Role-play checking in and later calling reception about a simple problem. Keep your speech calm and specific.');
add(9,'How are you feeling?','Body parts, haben expressions and wehtun',
'German often expresses physical states with haben: Ich habe Hunger (I am hungry), Ich habe Durst (I am thirsty), Ich habe Fieber (I have a fever). Other states use sein: Ich bin müde, krank or gesund. Learn the full phrase instead of matching English “am” mechanically. Body-part nouns have genders and often irregular plurals, so study them with their articles.~Wehtun is separable and means to hurt: Mein Kopf tut weh. With plural body parts, use tun: Meine Füße tun weh. You can also name pain as a noun: Ich habe Kopfschmerzen; Ich habe Bauchschmerzen. These common compounds generally use the plural Schmerzen. The person feeling pain can be shown with a dative pronoun: Der Rücken tut mir weh.~To ask how someone is, use Wie geht es dir? or the formal Wie geht es Ihnen? These are fixed expressions with dative pronouns. A simple answer is Gut, danke or Es geht. This lesson is language practice for describing a state, not medical advice. Practise clear statements about symptoms and time so you can communicate what you actually mean.',
'Ich habe Kopfschmerzen.=I have a headache.|Mein Kopf tut weh.=My head hurts.|Meine Füße tun weh.=My feet hurt.|Ich bin müde.=I am tired.|Wie geht es Ihnen?=How are you? (formal)|Ich habe Durst.=I am thirsty.',
[['Mein Kopf ___ weh.','tut','Kopf is singular, so use tut.',['tun','tust']],['Meine Füße ___ weh.','tun','Füße is plural, so use tun.',['tut','tust']],['I am thirsty: Ich ___ Durst.','habe','German expresses thirst with haben.',['bin','ist']],['Formal “How are you?”','Wie geht es Ihnen?','Formal dative you is capitalised Ihnen.',['Wie geht es Sie?','Wie gehen du?']]],
'Write six statements describing ordinary physical states or fictional symptoms. Use both haben and sein, plus one singular and one plural wehtun sentence.',
'Ich bin müde. Ich habe Durst. Mein Kopf tut weh. Meine Füße tun weh. Ich habe Husten. Heute bin ich gesund.',
'Answer Wie geht es Ihnen? Give two short details and practise the formal question yourself.');
add(9,'Please help me','Dative verbs and useful pronouns',
'Some common German verbs use a dative object where English does not show a special form. Helfen (help), danken (thank), gefallen (be pleasing to) and passen (fit) are useful examples. Ich helfe dir means I help you; Ich danke Ihnen means I thank you formally. Learn the case with the verb rather than assuming every object is accusative.~Dative pronouns are mir, dir, ihm, ihr, uns, euch, ihnen and Ihnen. Compare accusative Ich sehe dich (I see you) with dative Ich helfe dir (I help you). With helfen in the present, the vowel changes: du hilfst, er hilft. The sentence Er hilft mir contains er as subject and mir as the person helped.~Können Sie mir bitte helfen? is a valuable polite request. Mit also takes dative, so Mit wem? means with whom. You do not need to master every verb’s object pattern now. Build a small reference set: helfen + dative, sehen + accusative, mit + dative, für + accusative. Review the contrast by replacing a full noun with the correct pronoun.',
'Können Sie mir helfen?=Can you help me? (formal)|Ich helfe dir.=I help you.|Er hilft ihr.=He helps her.|Ich danke Ihnen.=I thank you. (formal)|Ich sehe dich.=I see you.|Kommst du mit mir?=Are you coming with me?',
[['Ich helfe ___. (you, familiar)','dir','Helfen takes dative; du becomes dir.',['dich','du']],['Er ___ mir.','hilft','Helfen changes e to i with er.',['helft','helfen']],['Ich sehe ___. (you, familiar)','dich','Sehen takes a direct object, so use accusative dich.',['dir','du']],['Thank you formally: Ich danke ___.','Ihnen','Danken takes dative; formal Ihnen has a capital letter.',['Sie','Ihr']]],
'Write three polite requests with können and mir. Write three contrasts using helfen and sehen so you practise dir versus dich or ihm versus ihn.',
'Können Sie mir bitte helfen? Können Sie mir bitte das erklären? Ich helfe dir. Ich sehe dich. Er hilft ihr. Ich danke Ihnen.',
'Practise asking a receptionist, teacher and neighbour for help. Change between formal and familiar address.');
add(9,'What should I do?','Sollen, dürfen and informal commands',
'Sollen reports an instruction, expectation or advice: Ich soll mehr schlafen means I am supposed to sleep more. Formen: ich soll, du sollst, er soll, wir sollen, ihr sollt, sie/Sie sollen. Dürfen describes permission: ich darf, du darfst, er darf, wir dürfen, ihr dürft, sie/Sie dürfen. Both use an infinitive at the end.~Nicht dürfen means not being allowed: Hier darf man nicht rauchen. Nicht müssen means not having to: Du musst heute nicht arbeiten. The distinction matters. Man means people in general or one, not specifically a man. In questions, Darf ich …? asks permission: Darf ich hier sitzen? Können Sie …? usually asks for help or ability.~Informal commands to one person commonly use the stem: Komm! Trink! Mach! Many e-to-i changing verbs preserve the change: Lies! Iss! Gib! Commands to a familiar group use the ihr verb form without ihr: Kommt! Trinkt! A polite formal command keeps Sie: Kommen Sie bitte. Practise with harmless everyday instructions; these example phrases are grammar models rather than treatment advice.',
'Ich soll mehr schlafen.=I am supposed to sleep more.|Darf ich hier sitzen?=May I sit here?|Hier darf man nicht rauchen.=Smoking is not permitted here.|Du musst heute nicht arbeiten.=You do not have to work today.|Komm bitte hierher!=Please come here!|Lesen Sie bitte den Text.=Please read the text. (formal)',
[['Not allowed: Du ___ hier nicht rauchen.','darfst','Darfst nicht expresses prohibition.',['musst','sollst']],['I am supposed to: Ich ___ lernen.','soll','Ich uses soll; add -st only for the du form sollst.',['sollst','sollen']],['Ask permission to sit.','Darf ich hier sitzen?','Darf ich asks whether an action is permitted.',['Muss ich hier sitzen?','Ich sitze darf?']],['Informal command to one person: ___.','Komm bitte!','Use the verb stem for kommen in the du imperative.',['Kommst bitte!','Kommen du bitte!']]],
'Create four signs stating permission or prohibition. Write two informal requests and two formal requests, then contrast something forbidden with something not required.',
'Hier darf man nicht rauchen. Hier darf man sitzen. Komm bitte! Lesen Sie bitte den Text. Du musst heute nicht arbeiten. Du darfst hier nicht parken.',
'Explain two signs, ask permission for two actions and give a polite instruction in formal and familiar forms.');
add(9,'At the doctor’s reception','Symptom messages and appointment dialogues',
'At a reception desk, clarity matters more than complicated grammar. Begin with Guten Tag, ich brauche einen Termin. Give your name and a short description: Ich habe Husten. Mein Hals tut weh. If asked Seit wann?, you are being asked since when or for how long. Useful fixed answers are seit gestern and seit zwei Tagen.~Seit takes the dative. For this stage, learn seit zwei Tagen and seit einer Woche as chunks. For a state continuing now, German commonly uses present tense: Ich bin seit zwei Tagen krank. You do not need an English-style present-perfect construction. To say yesterday’s state, use Gestern war ich krank. The time expression changes the meaning.~A telephone message should include a callback detail or a question about an available time. Listen for the day and clock time and repeat them. If an unfamiliar word blocks understanding, say Was bedeutet das? or Können Sie das bitte wiederholen? This practice is for describing symptoms and arranging help; it does not diagnose symptoms or advise on treatment.',
'Ich brauche einen Termin.=I need an appointment.|Mein Hals tut weh.=My throat hurts.|Seit wann?=Since when / for how long?|Ich bin seit zwei Tagen krank.=I have been ill for two days.|Haben Sie heute einen Termin frei?=Do you have an appointment available today?|Können Sie das bitte wiederholen?=Could you please repeat that?',
[['Seit wann asks about ___.','when the condition started','Seit wann asks since when or how long.',['the price','the address']],['Since yesterday: seit ___.','gestern','Gestern means yesterday; seit gestern means since yesterday.',['morgen','heute Abend']],['I have been ill for two days: Ich ___ seit zwei Tagen krank.','bin','German uses present tense for a state continuing now.',['habe','hatte']],['Ask for repetition politely.','Können Sie das bitte wiederholen?','The infinitive wiederholen closes the modal question.',['Sie bitte wiederholt?','Können wiederholen Sie das bitte?']]],
'Write a fictional 30-word appointment request: name, two symptoms, duration and an available time. Reply as the receptionist with a clear appointment offer.',
'Guten Tag, ich heiße Sami Ali. Ich habe Husten. Mein Hals tut weh. Ich bin seit zwei Tagen krank. Haben Sie heute einen Termin frei? Ich kann um elf Uhr kommen.',
'Record both sides of the receptionist conversation. Check that the appointment time is repeated accurately.');
add(10,'Does it fit?','Clothes, colours and gefallen versus mögen',
'For clothing, learn the noun and article: die Jacke, das Hemd, der Pullover, die Hose. German Hose is grammatically singular for a pair of trousers. Colours after sein keep their base form: Die Jacke ist blau. To avoid adjective endings for now, ask for an item in a colour: Haben Sie die Jacke in Blau?~Gefallen has a different perspective from English “like”: Die Jacke gefällt mir literally means the jacket is pleasing to me. The jacket is the subject and mir is dative. Plural shoes require gefallen: Die Schuhe gefallen mir. Passen behaves similarly: Die Jacke passt mir; Die Schuhe passen mir. To name yourself as the subject instead, use Ich mag die Jacke.~Ask Welche Größe brauchen Sie? or Haben Sie Größe 40? Anprobieren is separable: Ich probiere die Jacke an. With a modal, it stays together: Kann ich die Jacke anprobieren? Say too small or too big with zu: Sie ist zu klein. Once you decide, Ich nehme sie means I will take it, referring to the feminine Jacke.',
'Die Jacke ist blau.=The jacket is blue.|Die Jacke gefällt mir.=I like the jacket.|Die Schuhe passen mir.=The shoes fit me.|Welche Größe brauchen Sie?=What size do you need? (formal)|Kann ich die Jacke anprobieren?=May I try on the jacket?|Ich nehme sie.=I will take it. (the jacket)',
[['Die Jacke ___ mir. (pleases)','gefällt','The singular jacket is the subject, so use gefällt.',['gefallen','gefällst']],['Die Schuhe ___ mir.','passen','Schuhe is plural, so use passen.',['passt','passe']],['Die Jacke ist ___ klein. (too)','zu','Zu before an adjective means too.',['sehr nicht','für']],['May I try on the jacket?','Kann ich die Jacke anprobieren?','The modal question keeps the infinitive at the end.',['Kann ich probiere die Jacke an?','Ich kann die Jacke an?']]],
'Write a shopping dialogue naming an item, colour and size. Include trying it on, a problem with the fit and a final decision. Use gefällt mir once.',
'Ich brauche eine Jacke. Haben Sie die Jacke in Blau? Ich brauche Größe 40. Kann ich sie anprobieren? Sie ist zu klein. Die Jacke in Größe 42 passt mir. Ich nehme sie.',
'Practise the exchange twice, first buying and then politely declining an item.');
add(10,'This one or that one?','Welcher, dieser and object pronouns',
'Welcher means which and changes with gender and case. In the nominative: welcher Pullover, welche Jacke, welches Hemd, welche Schuhe. In the accusative, masculine becomes welchen: Welchen Pullover nehmen Sie? Feminine welche and neuter welches keep their forms. Identify whether the noun is the subject or object before choosing the ending.~Dieser means this and follows a similar pattern: dieser Pullover, diese Jacke, dieses Hemd. As an accusative masculine object, use diesen Pullover. A simple way to answer a question is with an object pronoun: Ich nehme ihn for der Pullover; Ich nehme sie for die Jacke; Ich nehme es for das Hemd. Plural items use sie.~Pointing expressions are useful in a shop, but naming the noun clearly helps avoid confusion. Compare Dieser Pullover ist schön with Ich nehme diesen Pullover. The object form changes even though you are talking about exactly the same sweater. Practise subject and object sentences in pairs, then replace the repeated noun with a pronoun.',
'Welcher Pullover ist schön?=Which sweater is nice?|Welchen Pullover nehmen Sie?=Which sweater will you take? (formal)|Diese Jacke gefällt mir.=I like this jacket.|Ich nehme diesen Pullover.=I will take this sweater.|Ich nehme ihn.=I will take it. (the sweater)|Welches Hemd passt dir?=Which shirt fits you?',
[['Which sweater will you take? ___ Pullover nehmen Sie?','Welchen','Pullover is a masculine direct object, so use welchen.',['Welcher','Welches']],['This jacket: ___ Jacke.','diese','Jacke is feminine, so use diese.',['dieser','dieses']],['Der Pullover: Ich nehme ___.','ihn','Masculine accusative object pronoun is ihn.',['er','ihm']],['Das Hemd: Ich nehme ___.','es','Neuter accusative pronoun is es.',['ihn','er']]],
'Choose three imaginary items. Ask which one fits, describe it as this item, then say you will take it using a pronoun. Check masculine object endings.',
'Welcher Pullover ist schön? Dieser Pullover ist schön. Ich nehme diesen Pullover. Ich nehme ihn. Welche Jacke passt? Diese Jacke passt. Ich nehme sie.',
'Set out three objects and ask which one someone wants. Answer once with a full noun phrase and once with a pronoun.');
add(10,'A little better','Comparisons and preferences',
'To compare two things, many German adjectives add -er: klein → kleiner, billig → billiger, schnell → schneller. Some also change their vowel: groß → größer, alt → älter. Use als after a comparative to mean than: Diese Jacke ist billiger als der Mantel. Keep adjective comparisons after sein at first so you do not also need adjective endings.~Three frequent irregular sets are gut → besser → am besten; gern → lieber → am liebsten; viel → mehr → am meisten. Ich trinke lieber Tee means I prefer drinking tea. Am liebsten expresses your strongest preference: Ich trinke am liebsten Wasser. You can compare activities and quantities with these without learning every comparative adjective immediately.~For equal comparison, use so … wie: Das Hemd ist so teuer wie die Jacke. Do not use als in that equal comparison. A short shopping decision may combine a preference, price and fit: Die Jacke ist billiger, aber der Mantel passt besser. Practise with invented prices so you can focus on the language rather than research.',
'Die Jacke ist billiger als der Mantel.=The jacket is cheaper than the coat.|Dieser Pullover ist größer.=This sweater is bigger.|Ich trinke lieber Tee.=I prefer drinking tea.|Das Hemd passt besser.=The shirt fits better.|Ich lese am liebsten.=Reading is my favourite activity.|Das Hemd ist so teuer wie die Jacke.=The shirt is as expensive as the jacket.',
[['Comparative of gut?','besser','Gut has the irregular comparative besser.',['guter','mehr gut']],['Billiger ___ der Mantel.','als','Comparatives use als for than.',['wie','mit']],['I prefer tea: Ich trinke ___ Tee.','lieber','Lieber is the comparative of gern.',['besser','meisten']],['As expensive as: so teuer ___.','wie','Equal comparisons use so … wie.',['als','für']]],
'Create a comparison of two items with prices and sizes. Write four comparative sentences and three personal preferences using lieber or am liebsten.',
'Die Jacke kostet 40 Euro. Der Mantel kostet 80 Euro. Die Jacke ist billiger als der Mantel. Der Mantel ist größer. Ich trinke lieber Tee. Ich lese am liebsten.',
'Explain which of two items you would choose and give two simple reasons.');
add(10,'Paying & exchanging','Transactions, receipts and a practical complaint',
'When you decide to buy, say Ich nehme das or Ich nehme die Jacke. Ask Kann ich mit Karte bezahlen? for card payment; bar means cash. A receipt is der Kassenbon. You can ask Kann ich bitte den Kassenbon haben? The customer’s wording can be short as long as the object and request are clear.~For a simple exchange request, say Ich möchte die Jacke umtauschen. Umtauschen is separable: Ich tausche die Jacke um. With möchten it remains an infinitive at the end. State a factual problem: Sie ist zu klein or Sie ist kaputt. Ask Ist das möglich? rather than assuming a store’s rules; this lesson teaches conversation, not consumer law.~The past tense helps explain the transaction: Ich habe die Jacke gestern gekauft. The participle gekauft belongs at the end. You can then ask for another size or item. Before speaking, write the item, purchase day, problem and desired solution as four bullet points. Turn each into one short sentence and keep your tone polite.',
'Kann ich mit Karte bezahlen?=Can I pay by card?|Ich bezahle bar.=I am paying cash.|Kann ich bitte den Kassenbon haben?=May I have the receipt, please?|Ich möchte die Jacke umtauschen.=I would like to exchange the jacket.|Ich habe sie gestern gekauft.=I bought it yesterday.|Sie ist zu klein.=It is too small.',
[['Paying in cash means ___.','bar','Bar means in cash in a payment context.',['blau','bald']],['Ich möchte die Jacke ___.','umtauschen','With möchten, use the full infinitive at the end.',['tauscht um','umgetauscht']],['I bought it yesterday: Ich habe sie gestern ___.','gekauft','Kaufen has the regular participle gekauft.',['kaufen','kauft']],['Ask for the receipt: den ___.','Kassenbon','Der Kassenbon is the receipt; as a direct object, den.',['Koffer','Kopf']]],
'Write a six-turn exchange at a shop: describe a purchase, explain a problem, ask for an exchange and another size, then finish politely.',
'Guten Tag. Ich habe die Jacke gestern gekauft. Sie ist zu klein. Ich möchte sie umtauschen. Haben Sie Größe 42? Ist das möglich? Vielen Dank.',
'Practise a polite request with three key facts: item, purchase day and problem. Repeat once without your notes.');
add(11,'A day at work','Work routines, frequency and time-first sentences',
'Frequency words make a routine more informative: immer (always), oft (often), manchmal (sometimes), selten (rarely) and nie (never). In a simple subject-first sentence, they often come after the conjugated verb: Ich arbeite oft zu Hause. With a modal, they sit inside the frame: Ich muss manchmal am Samstag arbeiten.~A time phrase can start a statement, but the verb must still be second: Am Montag arbeite ich im Büro. Am Montag is one sentence part, even though it is two words. If you add frequency, keep the subject after the verb: Am Montag arbeite ich oft zu Hause. Do not insert a second subject-first clause after the time phrase.~Use beginnen and enden for courses and shifts: Der Kurs beginnt um neun Uhr und endet um zwölf Uhr. The repeated subject can be omitted after und when it remains the same. In working life, reliable small statements about availability matter more than complex descriptions. Practise telling a colleague when you work, when you take a break and when you can meet.',
'Ich arbeite oft zu Hause.=I often work from home.|Am Montag arbeite ich im Büro.=On Monday I work in the office.|Ich muss manchmal am Samstag arbeiten.=I sometimes have to work on Saturday.|Der Kurs beginnt um neun Uhr.=The course starts at nine.|Die Arbeit endet um fünf Uhr.=Work ends at five.|Ich habe nie am Sonntag einen Kurs.=I never have a course on Sunday.',
[['Often means ___.','oft','Oft expresses a frequent action.',['nie','selten']],['Am Montag ___ ich im Büro.','arbeite','The conjugated verb follows the first time phrase.',['ich arbeite','arbeiten']],['The course starts: Der Kurs ___.','beginnt','A singular third-person subject takes beginnt.',['beginnen','beginnst']],['Never means ___.','nie','Nie means never; selten is rarely and immer is always.',['immer','manchmal']]],
'Write a weekly work or study schedule with six sentences. Include three frequency words, two time-first sentences and one modal sentence.',
'Am Montag lerne ich Deutsch. Ich arbeite oft zu Hause. Der Kurs beginnt um neun Uhr. Ich muss manchmal am Samstag arbeiten. Am Sonntag habe ich frei.',
'Explain a week to an imaginary colleague and find a day when you both have time.');
add(11,'Joining your ideas','Und, aber, oder and denn',
'Use und to add, aber to contrast, oder to offer an alternative and denn to give a reason. These coordinating conjunctions link sentence parts without pushing the next clause’s verb to the end. Compare Ich lerne Deutsch, denn ich wohne in Berlin. After denn, ich is first and wohne is second within that clause.~With a shared subject, und can join actions compactly: Ich arbeite und lerne Deutsch. If the second clause has a new subject, name it: Ich arbeite und meine Schwester lernt. With aber and denn between full clauses, use a comma. For a choice, ask Möchtest du Tee oder Kaffee? You do not need a full clause on each side of oder.~You may encounter weil for because, but it uses a different verb-order pattern in standard German. For this beginner writing task, denn gives you a reliable way to explain a reason without adding a subordinate clause. Choose the connector based on meaning, then check that each full clause has the appropriate conjugated verb. Avoid making long chains that you cannot easily read aloud.',
'Ich lerne Deutsch, denn ich wohne in Berlin.=I learn German because I live in Berlin.|Ich habe Zeit, aber ich bin müde.=I have time, but I am tired.|Möchtest du Tee oder Kaffee?=Would you like tea or coffee?|Ich arbeite und lerne Deutsch.=I work and learn German.|Er kommt, aber sie bleibt zu Hause.=He is coming, but she is staying at home.|Ich komme nicht, denn ich bin krank.=I am not coming because I am ill.',
[['Give a reason: Ich komme nicht, ___ ich bin krank.','denn','Denn introduces a reason and preserves normal clause order.',['oder','aber']],['Offer a choice: Tee ___ Kaffee?','oder','Oder means or and presents alternatives such as tea or coffee.',['denn','aber']],['Which clause order is correct after denn?','denn ich bin krank','Denn does not send the verb to the end.',['denn ich krank bin','denn bin krank ich']],['Express contrast: Ich habe Zeit, ___ ich bin müde.','aber','Aber means but and introduces a contrast.',['und nicht','oder']]],
'Join eight short sentences into four pairs using und, aber, oder and denn. Check verb position separately on both sides of each connector.',
'Ich lerne Deutsch und ich lese viel. Ich habe Zeit, aber ich bin müde. Möchtest du Tee oder Wasser? Ich komme nicht, denn ich bin krank.',
'Make four short statements about your plans, adding a reason, a contrast, a choice and another action.');
add(11,'A message that works','Short emails, forms and appropriate register',
'A short German message should answer the task before worrying about style. Identify the recipient, purpose and the facts they need. For a friend, begin Hallo Nora or Liebe Nora and end Viele Grüße. For a formal message, Sehr geehrte Frau Weber or Sehr geehrter Herr Weber is conventional; Mit freundlichen Grüßen is a standard closing.~The formal/familiar choice must be consistent. A friend gets du, dich, dir and dein. A formal contact gets Sie, Ihnen and Ihr with capital letters. After a salutation followed by a comma, the next line traditionally continues in lowercase unless the first word must be capitalised, as with Sie or a noun. This is a writing convention, not a different spoken grammar.~A practical 30–40-word message often needs three points: why you are writing, a relevant detail, and a request or next step. Do not spend all your words on the greeting. In a form, read the field labels carefully: Vorname, Nachname, Geburtsdatum, Adresse and Unterschrift. Date formats normally use day, month and year. Check names and digits twice because small errors can change the message.',
'Sehr geehrte Frau Weber,=Dear Ms Weber, (formal)|Lieber Sami,=Dear Sami, (informal)|Können Sie mir bitte antworten?=Could you please reply to me?|Vielen Dank für Ihre Hilfe.=Thank you very much for your help. (formal)|Mit freundlichen Grüßen=Kind regards (formal)|Viele Grüße=Best wishes / regards',
[['A formal greeting for Ms Weber is ___.','Sehr geehrte Frau Weber,','Frau uses geehrte; Herr uses geehrter.',['Lieber Frau Weber,','Sehr geehrter Frau Weber,']],['Formal “your help”: ___ Hilfe.','Ihre','The formal possessive is capitalised; Hilfe is feminine.',['dein','ihren']],['Vorname means ___.','given name','Vorname is your given name; Nachname is your family name.',['family name','signature']],['A formal closing is ___.','Mit freundlichen Grüßen','This is a standard formal letter or email closing.',['Tschüss, du!','Gute Nacht!']]],
'Write a formal 30–40-word message asking a course office about the next course: start date, price and schedule. Use a suitable greeting and closing. Check that all three questions appear.',
'Sehr geehrte Frau Weber, ich möchte einen Deutschkurs besuchen. Wann beginnt der nächste Kurs? Wie viel kostet er? Ist der Kurs am Morgen oder am Abend? Vielen Dank für Ihre Hilfe. Mit freundlichen Grüßen, Sami Ali',
'Read your message aloud as a phone enquiry. Replace written greeting and closing with spoken ones.');
add(11,'Next week, I’ll…','Future meaning with the present and plans',
'German often uses the present tense with a future time expression: Morgen fahre ich nach Berlin; Nächste Woche beginnt der Kurs. You do not need a special future form to talk about a clear plan. The time phrase makes the future meaning explicit. Keep the conjugated verb in second position after the time phrase.~Useful expressions include morgen (tomorrow), übermorgen (the day after tomorrow), nächste Woche (next week), nächsten Monat (next month) and nächstes Jahr (next year). Learn each as a phrase because their endings differ. Contrast gestern with morgen and letzte Woche with nächste Woche. If you have several plans, state them in chronological order.~Wollen expresses intention, möchten a softer wish, and können an available possibility. Ich will nächste Woche lernen is an intention; Ich möchte nach Berlin fahren is a wish. A plan can also include a condition you have not resolved: Ich weiß es noch nicht means I do not know yet. At A1, being able to express uncertainty simply is useful and honest communication.',
'Morgen fahre ich nach Berlin.=Tomorrow I am going to Berlin.|Nächste Woche beginnt der Kurs.=The course starts next week.|Ich möchte nächstes Jahr reisen.=I would like to travel next year.|Wir wollen am Samstag lernen.=We want to study on Saturday.|Übermorgen habe ich Zeit.=I have time the day after tomorrow.|Ich weiß es noch nicht.=I do not know yet.',
[['Tomorrow means ___.','morgen','Morgen is tomorrow; gestern is yesterday.',['gestern','immer']],['Nächste Woche ___ der Kurs.','beginnt','The present tense can express a future event when the time is clear.',['der beginnt','beginnen']],['Next year is ___.','nächstes Jahr','Learn the time phrase with its ending.',['nächste Jahr','nächsten Jahr']],['Express uncertainty.','Ich weiß es noch nicht.','This means I do not know yet.',['Ich bin kein wissen.','Ich nicht weiß es.']]],
'Write plans for tomorrow, next week and next year. Include a firm plan, a wish, an intention and something undecided. Ask a friend about one of their plans.',
'Morgen lerne ich Deutsch. Nächste Woche beginnt mein Kurs. Ich möchte nächstes Jahr reisen. Wir wollen am Samstag lernen. Wohin fährst du? Ich weiß es noch nicht.',
'Give a one-minute plan for the next week. Use a time phrase at the start of at least two sentences.');
add(12,'Whatever the weather','Weather, seasons and impersonal es',
'Weather statements often use es as a grammatical subject: Es regnet, es schneit, es ist kalt. Unlike a pronoun referring to a previously named thing, this es does not need an identifiable object. Do not omit it just because the English weather idea feels obvious. With a time phrase first, the verb still comes second: Heute regnet es.~Seasons and months usually use im: im Frühling, im Sommer, im Herbst, im Winter. Days use am and clock times use um. Weather can help you combine a description and plan: Es regnet, aber wir gehen ins Museum. To describe yesterday’s weather, use war for a state: Gestern war es kalt. For today and tomorrow, present tense with the time word is enough for a simple description or forecast report.~Temperatures may be given as Grad: Es sind zwanzig Grad. In everyday speech you will also hear Es ist zwanzig Grad warm. Focus on recognising the number and whether it is warm or cold. Practise matching an activity to a season and explaining your choice with denn. Weather gives familiar content for reviewing sentence order rather than requiring many new grammar rules.',
'Heute regnet es.=It is raining today.|Es ist kalt.=It is cold.|Im Sommer ist es warm.=It is warm in summer.|Gestern war es kalt.=It was cold yesterday.|Es sind zwanzig Grad.=It is twenty degrees.|Es regnet, aber wir gehen ins Museum.=It is raining, but we are going to the museum.',
[['Today it rains: Heute ___ es.','regnet','The verb follows Heute and the subject es comes next.',['es regnet','regnen']],['In summer: ___ Sommer.','im','Seasons take im, like months; weekdays instead take am.',['am','um']],['Yesterday it was cold: Gestern ___ es kalt.','war','War describes a past state.',['hatte','waren']],['Weather subject in Es regnet?','es','German normally includes the impersonal es.',['man','ich']]],
'Write a four-day weather diary, two past days and two present/future days. Suggest an activity for each day and give one reason using denn.',
'Gestern war es kalt. Heute regnet es. Wir gehen ins Museum. Morgen ist es warm. Wir fahren mit dem Fahrrad. Im Sommer reise ich gern.',
'Give a short weather report and suggest a weekend plan. Include a backup indoor activity.');
add(12,'Read the world around you','Notices, opening hours and reading strategies',
'At A1, reading is often about finding a useful fact in a short text. Before reading every word, identify the text type: a notice, advert, message, timetable or form. Then identify the question you need to answer. A sign saying Sonntag geschlossen answers whether you can visit on Sunday; you do not need to translate a whole paragraph to use it.~Look carefully at negation, days, times and ranges. Geöffnet means open, geschlossen means closed. Von Montag bis Freitag covers Monday through Friday, but a separate holiday note can change the practical meaning. Ab zehn Uhr means from ten onward; bis zehn Uhr means until ten. These small words reverse what a number tells you.~Do not answer from general knowledge when a text gives a different fact. If a café advert says only cash, choose according to the notice. When information is absent, recognise that it is not stated rather than inventing an answer. After reading, explain the decision in one plain sentence, then check the exact words that support it. This prepares you for everyday notices and basic reading tasks.',
'Am Sonntag geschlossen.=Closed on Sunday.|Geöffnet von Montag bis Freitag.=Open Monday to Friday.|Ab zehn Uhr geöffnet.=Open from ten.|Heute nur bis zwölf Uhr.=Today only until twelve.|Bitte hier warten.=Please wait here.|Nur Barzahlung.=Cash payment only.',
[['Ab zehn Uhr geöffnet means ___.','Open from ten.','Ab marks a starting point.',['Closed at ten.','Open until ten.']],['Nur Barzahlung means ___.','Cash only.','Nur means only; Barzahlung means cash payment.',['Card only.','Free entry.']],['Am Sonntag geschlossen: can you visit on Sunday?','No.','Geschlossen means closed, so the notice rules out a Sunday visit.',['Yes.','Only after ten.']],['Bis zwölf Uhr means ___.','until twelve','Bis marks the end point; ab marks the starting point.',['from twelve','at two']]],
'Create three useful notices for a café, museum and course office. Include opening times, one closure and one restriction. Write a question and answer for each notice.',
'Café: Montag bis Freitag, 8–18 Uhr. Nur Barzahlung. Museum: Am Sonntag geschlossen. Kursbüro: Heute nur bis zwölf Uhr. Kann ich am Sonntag ins Museum gehen? Nein.',
'Read each notice aloud and explain in German when someone can visit or what they should do.');
add(12,'A conversation you can handle','Requests, repair strategies and speaking turns',
'You do not need to understand every word to participate in a beginner conversation. You need to recognise the topic, take a short turn and ask for help when necessary. Useful repair phrases are Wie bitte?, Noch einmal, bitte, Können Sie bitte langsam sprechen? and Was bedeutet das? These are tools to keep the conversation going, not apologies for learning.~For a request, use Können Sie mir bitte … geben? or Kannst du mir bitte … geben? Match the register to the person. Ask an information question with a W-word: Wo ist …?, Wann beginnt …?, Wie viel kostet …? A full answer can be short. Include the exact detail asked for; do not respond to a price question only by describing the object.~Practise turn-taking with a three-part pattern: react, answer, ask back. For example: Ja, gern. Ich habe am Samstag Zeit. Und du? To confirm a plan, repeat its day, time and place. If you cannot remember a word, use a simpler known expression rather than stopping. Record role-plays as both speakers, leaving a pause for the answer so you can reuse the recording as a practice partner.',
'Können Sie mir bitte das Buch geben?=Could you please give me the book?|Kannst du bitte langsam sprechen?=Can you please speak slowly? (informal)|Was bedeutet das?=What does that mean?|Also am Samstag um zehn Uhr?=So, on Saturday at ten?|Ja, gern. Und du?=Yes, gladly. And you?|Ich verstehe das nicht.=I do not understand that.',
[['Politely ask a stranger to speak slowly.','Können Sie bitte langsam sprechen?','Use formal Sie and keep the infinitive at the end.',['Kannst Sie langsam?','Du sprechen langsam!']],['What does Was bedeutet das? ask?','What does that mean?','Bedeuten means to mean; this phrase asks for an explanation.',['Where is that?','How much is that?']],['A useful plan confirmation repeats ___.','day, time and place','Those details let both people verify the same arrangement.',['only your name','only the weather']],['I don’t understand: Ich ___ das nicht.','verstehe','Verstehen takes the regular ich ending -e.',['versteht','verstanden']]],
'Write three mini role-plays: borrow an item, ask directions and arrange a meeting. Include a repair phrase in each. Remove the model and rewrite the key requests.',
'Können Sie mir bitte das Buch geben? Ja, gern. Danke! Wo ist der Bahnhof? Gehen Sie links. Wie bitte? Treffen wir uns am Samstag um zehn Uhr? Ja, gern.',
'Record only the questions and leave five seconds of silence after each. Play them back and answer spontaneously without looking.');
add(12,'Your A1 dress rehearsal','Four skills, honest self-assessment and a next-step plan',
'Bring your skills together in a realistic practice session. Reading: identify dates, prices, locations and negation in a short notice. Listening: play the unit exchange with the text hidden, write the day, time and meeting place, then listen a second time. Speaking: introduce yourself, ask three information questions and make three polite requests. Writing: produce a short message covering all the requested points.~Do the first attempt without your notes, then use the model and explanations to diagnose gaps. An objective quiz score measures recognition and recall on these questions; it cannot certify independent conversation or writing quality. Your speaking checklist should ask whether your meaning is clear, the required details are present and you can respond without a full script. Your writing checklist should check task coverage before individual grammar errors.~Choose a specific next step from your weakest area. If listening is hard, repeat short recordings, transcribe and compare. If word retrieval is slow, use spaced review with your own sentences. If verbs are unreliable, return to the relevant grammar lesson and rewrite examples. After this rehearsal, use the official Goethe A1 practice materials linked in the Study room for an independent four-skill benchmark.',
'Ich heiße Sami und komme aus Ägypten.=My name is Sami and I come from Egypt.|Ich wohne in Kairo und lerne Deutsch.=I live in Cairo and am learning German.|Wann beginnt der Kurs?=When does the course start?|Können Sie mir bitte helfen?=Could you please help me?|Leider kann ich morgen nicht kommen.=Unfortunately I cannot come tomorrow.|Wir treffen uns am Samstag um zehn Uhr.=We are meeting on Saturday at ten.',
[['Choose a correct introduction.','Ich heiße Sami und komme aus Ägypten.','Both coordinated verbs agree with ich.',['Ich heißen Sami und kommt Ägypten.','Ich bin heiße Sami.']],['Choose a correct future plan.','Morgen fahre ich nach Berlin.','A time phrase makes the present-tense plan future; the verb stays second.',['Morgen ich fahre Berlin.','Ich morgen gefahren Berlin.']],['Choose a correct completed journey.','Ich bin nach Köln gefahren.','A journey with fahren uses sein plus gefahren.',['Ich habe nach Köln gefahrt.','Ich bin nach Köln fahren.']],['Choose the polite request.','Können Sie mir bitte helfen?','The modal is conjugated and helfen stays infinitive.',['Können Sie mich bitte hilft?','Sie helfen können mir?']]],
'Without the model, write a 30–40-word message to a friend: invite them to a museum, give the day, time and meeting place, and ask them to bring a ticket. Compare, revise, then write your next study goal.',
'Hallo Nora, hast du am Samstag Zeit? Wir können ins Museum gehen. Treffen wir uns um zehn Uhr am Bahnhof? Bring bitte deine Fahrkarte mit. Ich freue mich. Viele Grüße, Sami',
'Give a one-minute introduction, then ask three questions and make three requests without reading. Replay the recording and identify one clear strength and one specific improvement.');

export const curriculum={lessonMinutes:lessons.reduce((n,l)=>n+l.minutes,0),missionMinutes:units.length*40,reviewMinutes:36*10,totalMinutes:lessons.reduce((n,l)=>n+l.minutes,0)+units.length*40+36*10};
